/// Why a call on a type proved not to be generated is left unchanged.
const NOT_GENERATED: &str = "the receiver resolves to a type that is not generated by this crate's `api!` declarations (a same-named setter, or a `Deref` to a generated type, is left for review)";

/// Why a call that is not proved either way is left unchanged.
const UNPROVED_CALL: &str = "the call could not be proved to reach the generated setter: its receiver was not resolved to a generated Concord type through declarations, `use` imports, typed bindings, field owners, function results and generated methods (a method the generated surface does not define, or a name a macro may bind, makes it unknown), or a trait implemented in this crate may take precedence";

/// Why a call that may reach a v3-only generated method is not decided.
const UNPROVED_SHADOW: &str = "its receiver was not resolved to a generated type or to a type that is not generated (through declarations, `use` imports, typed bindings, field owners, function results and generated methods)";

/// Whether a call may reach, in v3, an inherent method that only the v3
/// generator defines (see [`CallerVisitor::shadow`]).
enum Shadow {
    /// Not a v3-only generated method of the receiver (or not reachable).
    None,
    /// The receiver is proved to be these generated types.
    Proved(Vec<(OwnerRef, V3Name)>),
    /// The receiver may be one of these generated types, and why it is not
    /// decided.
    Maybe(Vec<(OwnerRef, V3Name)>, String),
    /// The receiver is this type of another crate, and another crate of the
    /// run generates the name in v3.
    External(String),
    /// The receiver is unknown (why), and another crate of the run
    /// generates the name as a value control in v3.
    OtherCrate(String),
}

/// Whether a call reached, in v2.1, a generated method that v3 removed (see
/// [`CallerVisitor::removal`]).
enum Removal {
    /// Not a removed generated method of the receiver.
    None,
    /// The receiver is proved to be these generated types.
    Proved(Vec<(OwnerRef, RemovedName)>),
    /// The receiver may be one of these generated types, and why it is not
    /// decided.
    Maybe(Vec<(OwnerRef, RemovedName)>, String),
    /// The receiver is this type of another crate, and another crate of the
    /// run generated the name in v2.1 on a type v3 removed it from.
    External(String),
}

impl Removal {
    /// Only the removed methods whose callers are reported for a manual
    /// decision (`paginate` belongs to the paginate rule).
    fn manual(self) -> Self {
        let keep = |hits: Vec<(OwnerRef, RemovedName)>| {
            hits.into_iter()
                .filter(|(_, removed)| removed.disposition == Disposition::RemovedManualDiagnostic)
                .collect::<Vec<_>>()
        };
        match self {
            Self::Proved(hits) => {
                let hits = keep(hits);
                if hits.is_empty() {
                    Self::None
                } else {
                    Self::Proved(hits)
                }
            }
            Self::Maybe(hits, why) => {
                let hits = keep(hits);
                if hits.is_empty() {
                    Self::None
                } else {
                    Self::Maybe(hits, why)
                }
            }
            other => other,
        }
    }
}

/// The role of a generated type, as diagnostics name it.
const fn role_label(role: Role) -> &'static str {
    match role {
        Role::Builder => "client builder",
        Role::Built => "client",
        Role::Unbound => "unbound client root",
        Role::Scope => "scope handle",
        Role::UnboundScope => "unbound scope",
        Role::Request => "bound request",
        Role::Endpoint => "unbound intent",
    }
}

