#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum OwnerKind {
    Client,
    Scope,
    Endpoint,
}

#[derive(Debug)]
struct OwnerIndex {
    kind: OwnerKind,
    logical: String,
    children: Vec<usize>,
    /// `(logical value name, outer-optional)`, including an endpoint body.
    values: Vec<(String, bool)>,
    store_as: Vec<String>,
    /// The generated value methods (`set_*`, `omit_*`, `reset_*`), each
    /// taking `self` by value and returning the same type. For the client:
    /// the builder's (with its secret and provider setters,
    /// `configure_http`, `configure_runtime` and `retry`).
    methods: Vec<String>,
    /// An endpoint with a `paginate` clause (its request has `paginate`).
    paginated: bool,
    /// An endpoint with a body (its unbound intent is then not `Clone`).
    has_body: bool,
    /// The value controls v3 generates for this owner's values that v2.1
    /// did not (see [`v3_value_names`]), before removing names v2.1 also
    /// generates for another value.
    v3_values: Vec<V3Name>,
}

/// A method name the v3 generator defines as an inherent method of a
/// generated type (and v2.1 did not): an application trait method of that
/// name, which v2.1 calls reached, is shadowed by it in v3.
#[derive(Clone, Debug)]
struct V3Name {
    name: String,
    /// Its arguments besides the receiver: a call with another arity cannot
    /// select it silently (it fails to compile in v3 instead).
    arity: usize,
    /// It takes `&self` (else `self`): only then does auto-deref through a
    /// reference or shared pointer reach it (a `self` method is reached
    /// only through a `Box`).
    by_ref: bool,
    /// What it is, for diagnostics.
    what: String,
}

impl V3Name {
    fn new(name: impl Into<String>, arity: usize, what: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            arity,
            by_ref: false,
            what: what.into(),
        }
    }

    /// The method takes `&self`.
    fn by_ref(mut self) -> Self {
        self.by_ref = true;
        self
    }
}

/// The value controls v3 generates for `value` beyond the v2.1 ones (the v3
/// macro's `controls_for`, MIGRATE-01): the conditional `set_x_if_some` of a
/// client value, an optional value and an initialized value, and the exact
/// replacement `replace_x` of an optional value. A required value of a scope
/// or endpoint has no controls in either version.
fn v3_value_names(names: &mut Vec<V3Name>, value: &ValueDecl, client: bool) {
    let name = &value.name.logical;
    let kind = if value.optional {
        "optional value"
    } else if value.initialized {
        "initialized value"
    } else {
        "client value"
    };
    if client || value.optional || value.initialized {
        names.push(V3Name::new(
            format!("set_{name}_if_some"),
            1,
            format!("the conditional setter of the {kind} `{name}`"),
        ));
    }
    if value.optional {
        names.push(V3Name::new(
            format!("replace_{name}"),
            1,
            format!("the exact replacement of the optional value `{name}`"),
        ));
    }
}

/// The core methods v3 generates on a generated type of `role` that v2.1 did
/// not: runtime binding on client and scope handles, the request controls,
/// the bound request's `description()`, and the traversal terminals of a
/// paginated endpoint's request. `migration::tests::surface_parity` checks
/// this table (with [`v3_value_names`] and the builder's
/// [`ClientIndex::v3_builder_names`]) against the members the v2.1 and v3
/// generators actually emit.
fn v3_core_names(role: Role, paginated: bool) -> Vec<V3Name> {
    let binding = |names: &mut Vec<V3Name>| {
        names.push(
            V3Name::new(
                "bind",
                1,
                "the runtime-endpoint binding method of client and scope handles",
            )
            .by_ref(),
        );
        names.push(
            V3Name::new(
                "plan_runtime",
                1,
                "the runtime-endpoint planning method of client and scope handles",
            )
            .by_ref(),
        );
    };
    let mut names = Vec::new();
    match role {
        Role::Built | Role::Scope => binding(&mut names),
        Role::Request => {
            names.push(V3Name::new(
                "cancel_with",
                1,
                "the request cancellation control",
            ));
            names.push(V3Name::new(
                "with_options",
                1,
                "the request call-options control",
            ));
            names.push(V3Name::new("control_summary", 0, "the request control summary").by_ref());
            // v2.1 generated `description()` only on the unbound intent
            // (`Role::Endpoint`), never on the bound request (R3-01).
            names.push(
                V3Name::new("description", 0, "the bound request's endpoint description").by_ref(),
            );
            if paginated {
                for terminal in ["pages", "collect_prefix", "collect_all"] {
                    names.push(V3Name::new(
                        terminal,
                        1,
                        format!("the traversal terminal `{terminal}` of a paginated request"),
                    ));
                }
            }
        }
        Role::Builder | Role::Unbound | Role::UnboundScope | Role::Endpoint => {}
    }
    names
}

/// What the migration does about one generated-member delta between the
/// v2.1 and v3 generators (R4-01). `migration::tests::surface_parity`
/// requires a disposition for every member a generator adds, removes or
/// re-signs on a generated type, and checks each one's requirements.
#[cfg_attr(not(test), allow(dead_code))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum Disposition {
    /// A v3-only member: callers are checked for shadowing an application
    /// method (`C3-MIGRATE-GENERATED-NAME-SHADOW`, [`V3Name`]).
    AddedShadowCheck,
    /// A member v3 removed: a call that reached it is reported for a manual
    /// decision (`C3-MIGRATE-GENERATED-MEMBER-REMOVED`), never rewritten.
    RemovedManualDiagnostic,
    /// An exact semantic rename the tool performs, to `to`; `test` is the
    /// migration test exercising it. No current delta is one.
    #[allow(dead_code)]
    AutomaticRename {
        to: &'static str,
        test: &'static str,
    },
    /// A member a dedicated migration rule handles (`rule`); `test` is the
    /// migration test exercising it.
    DedicatedMigrationRule {
        rule: &'static str,
        test: &'static str,
    },
    /// No call can change meaning, for the stated concrete reason.
    NoResolutionRisk(&'static str),
}

/// A generated inherent method v2.1 emits on a generated type and v3 does
/// not (R4-01). A call that reached it in v2.1 does not reach Concord in v3:
/// it fails to compile, or, when an application trait in scope provides a
/// method of the same name for the type, silently calls that trait method
/// (the inherent method used to take precedence).
#[derive(Clone, Debug)]
struct RemovedName {
    name: String,
    /// Its arguments besides the receiver (a call with another arity could
    /// not reach it in v2.1).
    arity: usize,
    /// It took `&self` (else `self`); read by the parity guard (a call's
    /// reachability is decided by the v2.1 dispatch, `generated_method`).
    #[cfg_attr(not(test), allow(dead_code))]
    by_ref: bool,
    /// What it was, for diagnostics.
    what: String,
    disposition: Disposition,
    /// The v3 replacement (or its absence) and why the call is not rewritten.
    advice: String,
    /// The v3 method a call may be renamed to by hand, if there is one.
    v3_name: Option<String>,
}

/// The paginate rule's disposition of the removed `paginate` (it rewrites a
/// proved `.paginate(PageLimit::X(n))` and reports every other form).
const PAGINATE_RULE: Disposition = Disposition::DedicatedMigrationRule {
    rule: "paginate terminal selection (`CallerVisitor::paginate`, `C3-MIGRATE-PAGINATE-*`)",
    test: "paginate_rule_owns_the_removed_paginate_member",
};

/// The core methods v2.1 generated on a generated type of `role` that v3
/// does not generate there (R4-01): the bound request's per-request debug
/// level, and the traversal entry `paginate` of a paginated endpoint's
/// request. The builder's custom-provider setters are in
/// [`ClientIndex::v21_removed_builder_names`]. `migration::tests::surface_parity`
/// checks these tables against the members the generators actually emit.
fn v21_removed_core_names(role: Role, paginated: bool) -> Vec<RemovedName> {
    let mut names = Vec::new();
    if role == Role::Request {
        names.push(RemovedName {
            name: "debug".to_owned(),
            arity: 1,
            by_ref: false,
            what: "the per-request debug-level control `debug(DebugLevel)`".to_owned(),
            disposition: Disposition::RemovedManualDiagnostic,
            advice: "v3 has no per-request debug level: the body-free debug level is runtime-wide (`configure_runtime(|runtime| runtime.debug(level))` on the client builder, which affects every request of the client), so there is no automatic equivalent.".to_owned(),
            v3_name: None,
        });
        if paginated {
            names.push(RemovedName {
                name: "paginate".to_owned(),
                arity: 1,
                by_ref: false,
                what: "the traversal entry `paginate(PageLimit)`".to_owned(),
                disposition: PAGINATE_RULE,
                advice: String::new(),
                v3_name: None,
            });
        }
    }
    names
}

#[derive(Debug)]
struct ClientIndex {
    name: String,
    owners: Vec<OwnerIndex>,
    /// `(file index, macro path offset)` of the declaring `api!` invocation.
    origin: Option<(usize, usize)>,
    /// v2.1 generates `Client::new()` only when no required value, secret,
    /// custom credential provider or rate limit (limiter) must be supplied.
    has_new: bool,
    /// The client declares credentials (it has a `credentials()` facade).
    has_credentials: bool,
    /// The builder methods v3 generates that v2.1 did not, besides value
    /// controls: the setter of a custom credential provider, named after the
    /// credential (v2.1 named it `<credential>_provider`).
    v3_builder_names: Vec<V3Name>,
    /// The builder methods v2.1 generated that v3 does not: the setter
    /// `<credential>_provider` of a custom credential provider (v3 names it
    /// after the credential and narrows its argument, see
    /// [`custom_provider_setter`]).
    v21_removed_builder_names: Vec<RemovedName>,
}

/// The removed v2.1 provider setter `<credential>_provider` of the custom
/// credential `credential`. It is not an exact rename of the v3 setter
/// `<credential>`: the v2.1 setter is generic over any `P: CredentialProvider`
/// whose `Material` is the declared provider's (stored boxed), the v3 one
/// takes exactly the declared provider type. The tool cannot prove the
/// argument's type, so the call is reported with the v3 name, not renamed.
fn custom_provider_setter(credential: &str) -> RemovedName {
    RemovedName {
        name: format!("{credential}_provider"),
        arity: 1,
        by_ref: false,
        what: format!("the provider setter of the custom credential `{credential}`"),
        disposition: Disposition::RemovedManualDiagnostic,
        advice: format!(
            "v3 names this setter after the credential: `{credential}(provider)`. It is not renamed automatically: the v2.1 setter accepted any `CredentialProvider` with the declared provider's `Material`, while the v3 setter takes exactly the declared provider type, so the tool cannot prove the argument keeps its meaning. Rename it to `.{credential}(provider)` when the argument is the declared provider type (otherwise supply one)."
        ),
        v3_name: Some(credential.to_owned()),
    }
}

/// The generated value methods of one declared value: `set_*` (for a client
/// value always, otherwise when the value is not a required constructor
/// argument), `omit_*` when it is optional and `reset_*` when initialized.
fn value_methods(methods: &mut Vec<String>, value: &ValueDecl, client: bool) {
    let name = &value.name.logical;
    if client || value.optional || value.initialized {
        methods.push(format!("set_{name}"));
    }
    if value.optional {
        methods.push(format!("omit_{name}"));
    }
    if value.initialized {
        methods.push(format!("reset_{name}"));
    }
}

/// Whether a declaration site or any site below it attaches a rate limit.
fn declares_rate_limits(children: &[Child]) -> bool {
    children.iter().any(|child| match child {
        Child::Scope(scope) => {
            !scope.site.rate_limits.is_empty() || declares_rate_limits(&scope.children)
        }
        Child::Endpoint(endpoint) => !endpoint.site.rate_limits.is_empty(),
    })
}

/// The v2.1 declarations of one crate and the crate's name-resolution model,
/// used to resolve caller code.
#[derive(Debug, Default)]
pub(crate) struct DeclIndex {
    clients: Vec<ClientIndex>,
    model: CrateModel,
    /// `(value name, optional)` of every value declared by the other crates
    /// of the migration run: a call of their setters from this crate is
    /// reported, never rewritten.
    other_crate_values: Vec<(String, bool)>,
    /// The v3-only generated method names of the other crates of the run
    /// (see [`DeclIndex::v3_only`]): a call of such a name on another crate's
    /// type is reported.
    other_crate_v3_names: Vec<(String, usize)>,
    /// The v3-only value controls (`replace_x`, `set_x_if_some`) of the other
    /// crates of the run: a call of such a name on an unknown receiver is
    /// reported, as for a setter of another crate's optional value.
    other_crate_v3_values: Vec<String>,
    /// Every v3-only generated method name of this crate (see
    /// [`DeclIndex::v3_only`]), computed once the declarations are indexed.
    v3_names: Vec<String>,
    /// Every generated method name of this crate that v3 removed and whose
    /// callers are reported for a manual decision (see
    /// [`DeclIndex::v3_removed`]), computed once the declarations are indexed.
    removed_names: Vec<String>,
    /// The same names, with their arity, of the other crates of the run: a
    /// call of such a name on another crate's type is reported.
    other_crate_removed_names: Vec<(String, usize)>,
    /// Every `extern crate` item of the crate's files: `(file, line, crate,
    /// alias)` (the alias is the crate itself without `as`).
    extern_crates: Vec<(PathBuf, usize, String, String)>,
    /// Per indexed file, whether a bare `api!` in it is Concord's.
    bare_api: std::collections::BTreeMap<PathBuf, Result<(), String>>,
}

impl DeclIndex {
    /// Indexes every declaration of one crate and models its modules, items
    /// and imports. Files that do not parse are reported when migrated.
    pub(crate) fn build(layout: &Layout, sources: &[(PathBuf, String)]) -> Self {
        let mut parsed = sources
            .iter()
            .filter_map(|(path, source)| {
                let parsed = parse_rust(source).ok()?;
                let imports = Imports::collect(&parsed.file);
                Some((path, parsed, imports))
            })
            .collect::<Vec<_>>();
        // Whether a bare `api!` is Concord's depends on its crate root.
        let proofs = {
            let files = parsed
                .iter()
                .map(|(path, parsed, imports)| SourceFile {
                    path,
                    parsed,
                    imports,
                })
                .collect::<Vec<_>>();
            CrateModel::bare_api_proofs(layout, &files)
        };
        let mut index = Self::default();
        for (path, file, _) in &parsed {
            let source = sources
                .iter()
                .find(|(candidate, _)| candidate == *path)
                .map_or("", |(_, source)| source.as_str());
            let mut collector = ExternCrates::default();
            collector.visit_file(&file.file);
            for (offset, name, alias) in collector.items {
                let offset = (offset + file.base).min(source.len());
                let line = source.as_bytes()[..offset]
                    .iter()
                    .filter(|byte| **byte == b'\n')
                    .count()
                    + 1;
                index
                    .extern_crates
                    .push((path.to_path_buf(), line, name, alias));
            }
        }
        for ((path, _, imports), proof) in parsed.iter_mut().zip(proofs) {
            index.bare_api.insert(path.to_path_buf(), proof.clone());
            imports.prove_bare_api(proof);
        }
        for (file, (_, parsed, imports)) in parsed.iter().enumerate() {
            for invocation in find_api_invocations(parsed, imports) {
                if let Ok(api) = syntax::parse_api(invocation.tokens, parsed.base) {
                    let client = index.add(&api);
                    index.clients[client].origin = Some((file, invocation.offset));
                }
            }
        }
        index.v3_names = index
            .v3_only_names()
            .into_iter()
            .map(|(name, _)| name)
            .collect();
        index.removed_names = index
            .v3_removed_names()
            .into_iter()
            .map(|(name, _)| name)
            .collect();
        let files = parsed
            .iter()
            .map(|(path, parsed, imports)| SourceFile {
                path,
                parsed,
                imports,
            })
            .collect::<Vec<_>>();
        let model = CrateModel::build(layout, &files, &|file, offset| {
            index
                .clients
                .iter()
                .position(|client| client.origin == Some((file, offset)))
                .map(|client| index.generated_items(client))
        });
        index.model = model;
        index
    }

    /// Every `extern crate` item of the crate: `(file, line, crate, alias)`.
    pub(crate) fn extern_crates(&self) -> &[(PathBuf, usize, String, String)] {
        &self.extern_crates
    }

    /// The module scope of one indexed source file.
    pub(crate) fn file_scope(&self, path: &std::path::Path) -> Option<(usize, ScopeId)> {
        self.model.file(path)
    }

    /// Whether a bare `api!` in the indexed file at `path` is proved to be
    /// Concord's by its crate; `None` for a file this index does not hold.
    pub(crate) fn bare_api_proof(&self, path: &std::path::Path) -> Option<Result<(), String>> {
        self.bare_api.get(path).cloned()
    }

    /// The public v2.1 generated items of one client, at its `api!`:
    /// `Client`, `ClientBuilder` and the support module `client` holding
    /// `Unbound`, one module per scope (with its `Scope` facade and `Unbound`)
    /// and each endpoint's `EndpointRequest` and unbound `Endpoint` type.
    fn generated_items(&self, client: usize) -> GeneratedItems {
        let name = &self.clients[client].name;
        let root = |role| OwnerRef {
            client,
            owner: 0,
            role,
        };
        GeneratedItems {
            client,
            types: vec![
                (name.clone(), root(Role::Built)),
                (format!("{name}Builder"), root(Role::Builder)),
            ],
            module: self.generated_module(client, 0, to_snake_case(name)),
        }
    }

    fn generated_module(&self, client: usize, owner: usize, name: String) -> GeneratedModule {
        let owners = &self.clients[client].owners;
        let reference = |owner, role| OwnerRef {
            client,
            owner,
            role,
        };
        let mut types = Vec::new();
        if owner == 0 {
            types.push(("Unbound".to_owned(), reference(0, Role::Unbound)));
        } else {
            types.push((
                to_pascal_case(&owners[owner].logical),
                reference(owner, Role::Scope),
            ));
            types.push(("Unbound".to_owned(), reference(owner, Role::UnboundScope)));
        }
        let mut modules = Vec::new();
        for &child in &owners[owner].children {
            let logical = &owners[child].logical;
            match owners[child].kind {
                OwnerKind::Scope => {
                    modules.push(self.generated_module(client, child, to_snake_case(logical)));
                }
                OwnerKind::Endpoint => {
                    let pascal = to_pascal_case(logical);
                    types.push((format!("{pascal}Request"), reference(child, Role::Request)));
                    types.push((pascal, reference(child, Role::Endpoint)));
                }
                OwnerKind::Client => {}
            }
        }
        GeneratedModule {
            name,
            types,
            modules,
        }
    }

    pub(crate) fn add(&mut self, api: &Api) -> usize {
        let client = &api.client;
        let mut methods = Vec::new();
        let mut v3_values = Vec::new();
        for value in &client.values {
            value_methods(&mut methods, value, true);
            v3_value_names(&mut v3_values, value, true);
        }
        methods.extend(client.secrets.iter().map(|secret| secret.logical.clone()));
        methods.extend(
            client
                .credentials
                .iter()
                .filter(|credential| credential.custom)
                .map(|credential| format!("{}_provider", to_snake_case(&credential.name.logical))),
        );
        methods.extend(
            ["configure_http", "configure_runtime", "retry"]
                .into_iter()
                .map(str::to_owned),
        );
        let required_value = client
            .values
            .iter()
            .any(|value| !value.optional && !value.initialized);
        let custom_provider = client
            .credentials
            .iter()
            .any(|credential| credential.custom);
        let rate_limits =
            !client.site.rate_limits.is_empty() || declares_rate_limits(&client.children);
        let mut index = ClientIndex {
            origin: None,
            name: client.name.logical.clone(),
            owners: vec![OwnerIndex {
                kind: OwnerKind::Client,
                logical: client.name.logical.clone(),
                children: Vec::new(),
                values: client
                    .values
                    .iter()
                    .map(|value| (value.name.logical.clone(), value.optional))
                    .collect(),
                store_as: Vec::new(),
                methods,
                paginated: false,
                has_body: false,
                v3_values,
            }],
            has_new: !required_value
                && client.secrets.is_empty()
                && !custom_provider
                && !rate_limits,
            has_credentials: !client.credentials.is_empty(),
            v3_builder_names: client
                .credentials
                .iter()
                .filter(|credential| credential.custom)
                .map(|credential| {
                    let name = to_snake_case(&credential.name.logical);
                    V3Name::new(
                        name.clone(),
                        1,
                        format!(
                            "the provider setter of the custom credential `{name}` (v2.1 `{name}_provider`)"
                        ),
                    )
                })
                .collect(),
            v21_removed_builder_names: client
                .credentials
                .iter()
                .filter(|credential| credential.custom)
                .map(|credential| custom_provider_setter(&to_snake_case(&credential.name.logical)))
                .collect(),
        };
        add_children(&mut index, 0, &client.children);
        for credential in &client.credentials {
            let Some(path) = &credential.endpoint_source else {
                continue;
            };
            let mut owner = 0;
            let mut found = true;
            for segment in path {
                match index.owners[owner]
                    .children
                    .iter()
                    .copied()
                    .find(|child| index.owners[*child].logical == *segment)
                {
                    Some(child) => owner = child,
                    None => {
                        found = false;
                        break;
                    }
                }
            }
            if found {
                index.owners[owner]
                    .store_as
                    .push(credential.name.logical.clone());
            }
        }
        self.clients.push(index);
        self.clients.len() - 1
    }

    pub(crate) fn is_empty(&self) -> bool {
        self.clients.is_empty()
    }

    /// `(value name, optional)` of every value this crate declares.
    pub(crate) fn value_names(&self) -> Vec<(String, bool)> {
        self.clients
            .iter()
            .flat_map(|client| client.owners.iter())
            .flat_map(|owner| owner.values.iter())
            .cloned()
            .collect()
    }

    /// Records the values declared by the other crates of the run.
    pub(crate) fn set_other_crate_values(&mut self, values: Vec<(String, bool)>) {
        self.other_crate_values = values;
    }

    /// Where a Concord-optional value named `name` is declared, for a
    /// diagnostic ("in this crate", or "by another crate of this migration
    /// run"); `None` when no crate of the run declares one.
    fn optional_value_owner(&self, name: &str) -> Option<&'static str> {
        let optional_here = self
            .clients
            .iter()
            .flat_map(|client| client.owners.iter())
            .flat_map(|owner| owner.values.iter())
            .any(|(value, optional)| value == name && *optional);
        if optional_here {
            return Some("in this crate");
        }
        self.other_crate_values
            .iter()
            .any(|(value, optional)| value == name && *optional)
            .then_some("by another crate of this migration run")
    }

    fn has_endpoint_credential(&self, name: &str) -> bool {
        self.clients
            .iter()
            .flat_map(|client| client.owners.iter())
            .any(|owner| owner.store_as.iter().any(|credential| credential == name))
    }

    fn owner(&self, reference: OwnerRef) -> &OwnerIndex {
        &self.clients[reference.client].owners[reference.owner]
    }

    /// The child navigation method `name` of a bound (`Client`, scope
    /// facade) or unbound (`Unbound`) owner: a scope or endpoint of the same
    /// kind.
    fn child(&self, reference: OwnerRef, name: &str, unbound: bool) -> Option<OwnerRef> {
        let owner = self.owner(reference);
        owner
            .children
            .iter()
            .copied()
            .find(|child| self.clients[reference.client].owners[*child].logical == name)
            .map(|child| {
                let role = match (self.clients[reference.client].owners[child].kind, unbound) {
                    (OwnerKind::Endpoint, false) => Role::Request,
                    (OwnerKind::Endpoint, true) => Role::Endpoint,
                    (OwnerKind::Scope | OwnerKind::Client, false) => Role::Scope,
                    (OwnerKind::Scope | OwnerKind::Client, true) => Role::UnboundScope,
                };
                OwnerRef {
                    client: reference.client,
                    owner: child,
                    role,
                }
            })
    }

    /// The generated inherent method `method` of one owner, as v2.1 emits
    /// it (only methods the generated surface defines advance a chain).
    fn generated_method(&self, owner: OwnerRef, method: &str) -> Option<Method> {
        let index = self.owner(owner);
        let value_method = || index.methods.iter().any(|name| name == method);
        let same = Method {
            by_ref: false,
            next: Next::Same,
        };
        let opaque = |by_ref| Method {
            by_ref,
            next: Next::Opaque,
        };
        let child = |unbound| {
            self.child(owner, method, unbound).map(|child| Method {
                by_ref: true,
                next: Next::Owner(child),
            })
        };
        match owner.role {
            Role::Builder if method == "build" => Some(Method {
                by_ref: false,
                next: Next::Built,
            }),
            Role::Builder => value_method().then_some(same),
            Role::Built => match method {
                "request" => Some(Method {
                    by_ref: true,
                    next: Next::Bound,
                }),
                "plan" => Some(opaque(true)),
                "credentials" if self.clients[owner.client].has_credentials => Some(opaque(true)),
                _ => child(false),
            },
            Role::Unbound => child(true),
            Role::Scope => {
                if value_method() {
                    Some(same)
                } else {
                    child(false)
                }
            }
            Role::UnboundScope => {
                if value_method() {
                    Some(same)
                } else {
                    child(true)
                }
            }
            Role::Request => match method {
                _ if value_method() => Some(same),
                "timeout" | "reset_timeout" | "debug" => Some(same),
                "paginate" if index.paginated => Some(opaque(false)),
                "response" => Some(opaque(false)),
                "plan" => Some(opaque(true)),
                _ => None,
            },
            Role::Endpoint => match method {
                _ if value_method() => Some(same),
                "description" => Some(opaque(true)),
                _ => None,
            },
        }
    }

    /// The names v3 generates as inherent methods of the generated type
    /// `owner` that v2.1 did not generate for it (MIGRATE-01): an application
    /// trait method of such a name, which a v2.1 call reached, is shadowed by
    /// the inherent method in v3.
    fn v3_only(&self, owner: OwnerRef) -> Vec<V3Name> {
        let index = self.owner(owner);
        let values = match (index.kind, owner.role) {
            (OwnerKind::Client, Role::Builder) => index
                .v3_values
                .iter()
                .chain(&self.clients[owner.client].v3_builder_names)
                .cloned()
                .collect(),
            (OwnerKind::Scope, Role::Scope | Role::UnboundScope)
            | (OwnerKind::Endpoint, Role::Request | Role::Endpoint) => index.v3_values.clone(),
            _ => Vec::new(),
        };
        values
            .into_iter()
            .chain(v3_core_names(owner.role, index.paginated))
            .filter(|candidate| self.generated_method(owner, &candidate.name).is_none())
            .collect()
    }

    /// The methods v2.1 generated as inherent methods of the generated type
    /// `owner` that v3 does not generate for it (R4-01): a call that reached
    /// one in v2.1 no longer reaches Concord in v3, and may reach an
    /// application trait method of the same name instead.
    fn v3_removed(&self, owner: OwnerRef) -> Vec<RemovedName> {
        let index = self.owner(owner);
        let builder = match (index.kind, owner.role) {
            (OwnerKind::Client, Role::Builder) => {
                self.clients[owner.client].v21_removed_builder_names.clone()
            }
            _ => Vec::new(),
        };
        builder
            .into_iter()
            .chain(v21_removed_core_names(owner.role, index.paginated))
            .filter(|candidate| self.generated_method(owner, &candidate.name).is_some())
            .collect()
    }

    /// Every removed generated method name of this crate whose callers are
    /// reported for a manual decision (see [`Self::v3_removed`]), with its
    /// arity, for the other crates of the run.
    pub(crate) fn v3_removed_names(&self) -> Vec<(String, usize)> {
        let mut names = self
            .generated_types()
            .into_iter()
            .flat_map(|owner| self.v3_removed(owner))
            .filter(|removed| removed.disposition == Disposition::RemovedManualDiagnostic)
            .map(|removed| (removed.name, removed.arity))
            .collect::<Vec<_>>();
        names.sort();
        names.dedup();
        names
    }

    /// Records the removed generated method names of the other crates of
    /// the run (see [`Self::v3_removed_names`]).
    pub(crate) fn set_other_crate_removed_names(&mut self, names: Vec<(String, usize)>) {
        self.other_crate_removed_names = names;
    }

    /// Every generated type of this crate, as `OwnerRef`s.
    fn generated_types(&self) -> Vec<OwnerRef> {
        let mut types = Vec::new();
        for (client, entry) in self.clients.iter().enumerate() {
            for (owner, index) in entry.owners.iter().enumerate() {
                let roles: &[Role] = match index.kind {
                    OwnerKind::Client => &[Role::Builder, Role::Built, Role::Unbound],
                    OwnerKind::Scope => &[Role::Scope, Role::UnboundScope],
                    OwnerKind::Endpoint => &[Role::Request, Role::Endpoint],
                };
                types.extend(roles.iter().map(|role| OwnerRef {
                    client,
                    owner,
                    role: *role,
                }));
            }
        }
        types
    }

    /// Every v3-only generated method name of this crate (see
    /// [`Self::v3_only`]) with its arity, for the other crates of the run.
    pub(crate) fn v3_only_names(&self) -> Vec<(String, usize)> {
        let mut names = self
            .generated_types()
            .into_iter()
            .flat_map(|owner| self.v3_only(owner))
            .map(|candidate| (candidate.name, candidate.arity))
            .collect::<Vec<_>>();
        names.sort();
        names.dedup();
        names
    }

    /// The v3-only value controls of this crate (see [`Self::v3_only`]).
    pub(crate) fn v3_only_value_names(&self) -> Vec<String> {
        let mut names = self
            .generated_types()
            .into_iter()
            .flat_map(|owner| {
                let values = &self.owner(owner).v3_values;
                self.v3_only(owner)
                    .into_iter()
                    .filter(|candidate| values.iter().any(|value| value.name == candidate.name))
                    .map(|candidate| candidate.name)
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        names.sort();
        names.dedup();
        names
    }

    /// Records the v3-only generated method names (all, and the value
    /// controls among them) of the other crates of the run.
    pub(crate) fn set_other_crate_v3_names(
        &mut self,
        names: Vec<(String, usize)>,
        values: Vec<String>,
    ) {
        self.other_crate_v3_names = names;
        self.other_crate_v3_values = values;
    }

    /// The client whose generated builder is named `name` (`ClientBuilder`).
    fn builder_client(&self, name: &str) -> Option<usize> {
        name.strip_suffix("Builder").and_then(|client| {
            self.clients
                .iter()
                .position(|candidate| candidate.name == client)
        })
    }

    /// Every generated type of this crate as the tool models it, with its
    /// v2.1 path and its v3-only names (see [`Self::v3_only`]), for the
    /// generated-surface parity test (`migration::tests::surface_parity`).
    #[cfg(test)]
    pub(crate) fn surface_inventory(&self) -> Vec<SurfaceRow> {
        fn walk(
            index: &DeclIndex,
            prefix: &str,
            module: &GeneratedModule,
            rows: &mut Vec<SurfaceRow>,
        ) {
            let prefix = format!("{prefix}{}::", module.name);
            for (name, owner) in &module.types {
                rows.push(index.surface_row(format!("{prefix}{name}"), *owner));
            }
            for nested in &module.modules {
                walk(index, &prefix, nested, rows);
            }
        }
        let mut rows = Vec::new();
        for client in 0..self.clients.len() {
            let items = self.generated_items(client);
            for (name, owner) in &items.types {
                rows.push(self.surface_row(name.clone(), *owner));
            }
            walk(self, "", &items.module, &mut rows);
        }
        rows
    }

    #[cfg(test)]
    fn surface_row(&self, path: String, owner: OwnerRef) -> SurfaceRow {
        SurfaceRow {
            path,
            role: owner.role,
            client: self.clients[owner.client].name.clone(),
            v3_only: self
                .v3_only(owner)
                .into_iter()
                .map(|name| (name.name, name.arity, name.by_ref))
                .collect(),
            v3_removed: self
                .v3_removed(owner)
                .into_iter()
                .map(|name| (name.name, name.arity, name.by_ref, name.disposition))
                .collect(),
        }
    }
}

/// One generated type of [`DeclIndex::surface_inventory`].
#[cfg(test)]
#[derive(Debug)]
pub(crate) struct SurfaceRow {
    /// Its v2.1 path (`ClientBuilder`, `client::scope::EndpointRequest`).
    pub(crate) path: String,
    pub(crate) role: Role,
    /// The declaring client's name.
    pub(crate) client: String,
    /// `(name, arity, by_ref)` of each v3-only generated method.
    pub(crate) v3_only: Vec<(String, usize, bool)>,
    /// `(name, arity, by_ref, disposition)` of each generated method v2.1
    /// emitted and v3 removed.
    pub(crate) v3_removed: Vec<(String, usize, bool, Disposition)>,
}

/// Collects the `extern crate` items of a file (at any depth): the offset of
/// the item, the crate and its alias.
#[derive(Default)]
struct ExternCrates {
    items: Vec<(usize, String, String)>,
}

impl<'ast> Visit<'ast> for ExternCrates {
    fn visit_item_extern_crate(&mut self, node: &'ast syn::ItemExternCrate) {
        let name = canonical(&node.ident);
        let alias = node
            .rename
            .as_ref()
            .map_or_else(|| name.clone(), |(_, alias)| canonical(alias));
        self.items
            .push((node.extern_token.span.byte_range().start, name, alias));
    }
}

fn add_children(index: &mut ClientIndex, parent: usize, children: &[Child]) {
    for child in children {
        let mut methods = Vec::new();
        let mut v3_values = Vec::new();
        let (kind, name, values, grandchildren, paginated, has_body) = match child {
            Child::Scope(scope) => {
                for value in &scope.params {
                    value_methods(&mut methods, value, false);
                    v3_value_names(&mut v3_values, value, false);
                }
                (
                    OwnerKind::Scope,
                    scope.name.logical.clone(),
                    scope
                        .params
                        .iter()
                        .map(|value| (value.name.logical.clone(), value.optional))
                        .collect::<Vec<_>>(),
                    Some(&scope.children),
                    false,
                    false,
                )
            }
            Child::Endpoint(endpoint) => {
                for value in &endpoint.params {
                    value_methods(&mut methods, value, false);
                    v3_value_names(&mut v3_values, value, false);
                }
                let mut values = endpoint
                    .params
                    .iter()
                    .map(|value| (value.name.logical.clone(), value.optional))
                    .collect::<Vec<_>>();
                if let Some(body) = &endpoint.body {
                    values.push((body.name.logical.clone(), body.optional));
                    if body.optional {
                        let body = &body.name.logical;
                        methods.push(format!("set_{body}"));
                        methods.push(format!("omit_{body}"));
                        v3_values.push(V3Name::new(
                            format!("set_{body}_if_some"),
                            1,
                            format!("the conditional setter of the optional request body `{body}`"),
                        ));
                        v3_values.push(V3Name::new(
                            format!("replace_{body}"),
                            1,
                            format!("the exact replacement of the optional request body `{body}`"),
                        ));
                    }
                }
                (
                    OwnerKind::Endpoint,
                    endpoint.name.logical.clone(),
                    values,
                    None,
                    endpoint.pagination.is_some(),
                    endpoint.body.is_some(),
                )
            }
        };
        let id = index.owners.len();
        index.owners.push(OwnerIndex {
            kind,
            logical: name,
            children: Vec::new(),
            values,
            store_as: Vec::new(),
            methods,
            paginated,
            has_body,
            v3_values,
        });
        index.owners[parent].children.push(id);
        if let Some(grandchildren) = grandchildren {
            add_children(index, id, grandchildren);
        }
    }
}

/// Why a receiver or a dispatch is unknown, when the tool can say precisely
/// (a `#[cfg]`-gated binding, a trait the model cannot see, another crate's
/// type); the generic [`UNPROVED_CALL`] otherwise. Diagnostics only: two
/// reasons never make receivers or dispatches differ.
#[derive(Clone, Debug, Default)]
struct Why(Option<Rc<str>>);

impl PartialEq for Why {
    fn eq(&self, _: &Self) -> bool {
        true
    }
}

impl Why {
    fn new(reason: impl Into<String>) -> Self {
        Self(Some(Rc::from(reason.into())))
    }

    fn of(reason: Option<String>) -> Self {
        Self(reason.map(Rc::from))
    }

    fn text(&self) -> Option<&str> {
        self.0.as_deref()
    }
}

#[derive(Clone, Debug, PartialEq)]
enum Receiver {
    /// Proved to be these generated types.
    Owners(Vec<OwnerRef>),
    RuntimeConfig,
    HttpConfig,
    /// A crate-local struct, proved by declaration identity; its fields are
    /// typed through its own declaration.
    Struct(usize),
    /// A standard wrapper or reference of a generated type or crate-local
    /// struct (built with [`Receiver::wrap`]).
    Wrapped(Wrapper, Box<Receiver>),
    /// A type of another crate (not the standard library or Concord), by
    /// its resolved path: possibly generated by that crate's `api!`.
    External(Vec<String>),
    /// Proved not to be a type generated by this crate's declarations.
    Foreign,
    Unknown(Why),
}

impl Receiver {
    /// Unknown, for the generic reason.
    fn unknown() -> Self {
        Self::Unknown(Why::default())
    }

    fn from_type(resolved: TypeRes) -> Self {
        Self::from_traced(resolved, None)
    }

    /// [`Self::from_type`], keeping the precise reason of an unknown type.
    fn from_traced(resolved: TypeRes, cause: Option<String>) -> Self {
        match resolved {
            TypeRes::Generated(owners) => Self::Owners(owners),
            TypeRes::Struct(id) => Self::Struct(id),
            TypeRes::Wrapped(wrapper, inner) => {
                Self::wrap(wrapper, Self::from_traced(*inner, cause))
            }
            TypeRes::External(path) => match concord_config_builder(&path) {
                Some(true) => Self::RuntimeConfig,
                Some(false) => Self::HttpConfig,
                None if path.first().is_some_and(|first| {
                    is_concord_crate(first) || matches!(first.as_str(), "std" | "core" | "alloc")
                }) =>
                {
                    Self::Foreign
                }
                None => Self::External(path),
            },
            TypeRes::Foreign => Self::Foreign,
            TypeRes::Unknown => Self::Unknown(Why::of(cause)),
        }
    }

    /// `wrapper` around `inner` (a wrapper of anything but a generated type
    /// or crate-local struct is simply not generated).
    fn wrap(wrapper: Wrapper, inner: Self) -> Self {
        match inner {
            Self::Owners(_) | Self::Struct(_) | Self::Wrapped(..) => {
                Self::Wrapped(wrapper, Box::new(inner))
            }
            Self::Unknown(why) => Self::Unknown(why),
            Self::RuntimeConfig | Self::HttpConfig | Self::External(_) | Self::Foreign => {
                Self::Foreign
            }
        }
    }

    /// The type this receiver denotes, to compare with trait receivers.
    fn as_type(&self) -> Option<TypeRes> {
        match self {
            Self::Owners(owners) => Some(TypeRes::Generated(owners.clone())),
            Self::Struct(id) => Some(TypeRes::Struct(*id)),
            Self::Wrapped(wrapper, inner) => {
                Some(TypeRes::Wrapped(*wrapper, Box::new(inner.as_type()?)))
            }
            Self::RuntimeConfig
            | Self::HttpConfig
            | Self::External(_)
            | Self::Foreign
            | Self::Unknown(_) => None,
        }
    }

    /// Why this receiver is unknown, if it is.
    fn why(&self) -> Why {
        match self {
            Self::Unknown(why) => why.clone(),
            _ => Why::default(),
        }
    }
}

/// Where a method call dispatches.
#[derive(Clone, Debug, PartialEq)]
enum Dispatch {
    /// Proved to be the generated inherent method of these owners.
    Generated(Vec<OwnerRef>),
    /// The receiver is proved to be a generated type that has no generated
    /// method of this name: the call is the application's own method.
    Undefined,
    /// A method of Concord's runtime or HTTP configuration builder.
    Config,
    /// Proved not to reach a generated method, with the reason.
    Elsewhere(String),
    /// Not proved either way (with the precise reason, when there is one).
    Unknown(Why),
}

impl Dispatch {
    /// Unknown, for the generic reason.
    fn unknown() -> Self {
        Self::Unknown(Why::default())
    }
}

/// What a generated method returns.
#[derive(Clone, Copy, Debug)]
enum Next {
    /// The same generated type (a value method).
    Same,
    /// Another generated type (child navigation).
    Owner(OwnerRef),
    /// `Result<Client, _>` (`ClientBuilder::build`).
    Built,
    /// The request bound from the argument (`Client::request`).
    Bound,
    /// A type this tool does not follow.
    Opaque,
}

/// One generated inherent method: whether it takes `&self` (else `self`),
/// and what it returns.
#[derive(Clone, Copy, Debug)]
struct Method {
    by_ref: bool,
    next: Next,
}

/// Local variable bindings of one lexical scope. An `opaque` layer follows a
/// statement macro (or a pattern macro) that may introduce bindings this tool
/// cannot see: names bound before it are unknown after it.
struct Bindings {
    names: HashMap<String, Receiver>,
    opaque: bool,
    /// The block scope of the crate model this layer holds the `let`
    /// bindings of (`None` for parameters, patterns and macro layers). Its
    /// items shadow bindings of outer layers (see [`CallerVisitor::local`]).
    block: Option<ScopeId>,
    /// Identifies the exact contents of this layer: a new layer, and every
    /// change of one, takes a fresh identifier (see [`CallerVisitor::memo`]).
    id: u64,
}

/// A fresh [`Bindings::id`].
fn fresh_bindings_id() -> u64 {
    static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
}

impl Default for Bindings {
    fn default() -> Self {
        Self {
            names: HashMap::new(),
            opaque: false,
            block: None,
            id: fresh_bindings_id(),
        }
    }
}

/// What a memoized method call depends on: the call (by the offset of its
/// method name, which also identifies a macro argument parsed again), the
/// name it would be rewritten to, the scope, the generic parameters and
/// `Self` types in scope, and the identifiers of every binding layer.
type MemoKey = (
    usize,
    Option<String>,
    Option<ScopeId>,
    usize,
    usize,
    Vec<u64>,
);

pub(crate) struct CallerInput<'a> {
    pub(crate) source: &'a str,
    pub(crate) base: usize,
    pub(crate) index: &'a DeclIndex,
    pub(crate) imports: &'a Imports,
    /// Whether the file uses Concord (imports it or declares an `api!`).
    /// Library-internal files that define these APIs are not caller code.
    pub(crate) concord_file: bool,
    /// The file's index and module scope in the crate model; `None` resolves
    /// no type (every receiver stays unproved).
    pub(crate) location: Option<(usize, ScopeId)>,
}

pub(crate) fn migrate(
    file: &syn::File,
    input: &CallerInput<'_>,
    edits: &mut EditSet,
    diagnostics: &mut Vec<RawDiagnostic>,
) {
    let mut visitor = CallerVisitor {
        source: input.source,
        base: input.base,
        index: input.index,
        imports: input.imports,
        file: input.location.map(|(file, _)| file),
        scope: input.location.map(|(_, scope)| scope),
        generics: Vec::new(),
        self_types: Vec::new(),
        concord_file: input.concord_file,
        scopes: vec![Bindings::default()],
        mounted: input
            .location
            .and_then(|(file, _)| input.index.model.other_mount(file))
            .map(|other| {
                format!(
                    "this file is mounted more than once (it is also {other}), so its paths may name other items in the other mount, and the tool proves a rewrite in one mount only"
                )
            }),
        memo: std::cell::RefCell::new(HashMap::new()),
        edits,
        diagnostics,
        page_limit_references: Vec::new(),
        rewritten_arguments: Vec::new(),
        prefix_awaited: Vec::new(),
        paginated_request_references: Vec::new(),
        rewritten_paginated_request: Vec::new(),
        imported_terminals: Vec::new(),
    };
    visitor.visit_file(file);
    visitor.finish_page_limit(file);
    visitor.finish_paginated_request(file);
}

struct CallerVisitor<'a, 'o> {
    source: &'a str,
    base: usize,
    index: &'a DeclIndex,
    imports: &'a Imports,
    /// This file's index in the crate model.
    file: Option<usize>,
    /// The innermost module or block scope; `None` when the tool cannot place
    /// the current code in the crate model.
    scope: Option<ScopeId>,
    /// Generic type parameters in scope (they shadow item names).
    generics: Vec<String>,
    /// `Self` of each enclosing `impl` (Unknown inside a trait).
    self_types: Vec<TypeRes>,
    concord_file: bool,
    scopes: Vec<Bindings>,
    /// Why no call of this file is proved: it is compiled more than once
    /// (see [`CrateModel::other_mount`]).
    mounted: Option<String>,
    /// The dispatch and result of every method call examined, for the exact
    /// state it was examined in: a chain of `n` calls is inferred once per
    /// call instead of once per call and receiver (quadratic).
    memo: std::cell::RefCell<HashMap<MemoKey, (Dispatch, Receiver)>>,
    edits: &'o mut EditSet,
    diagnostics: &'o mut Vec<RawDiagnostic>,
    page_limit_references: Vec<usize>,
    rewritten_arguments: Vec<Rng>,
    /// `paginate` method-name offsets whose Prefix result is awaited
    /// directly, with whether a `?` follows the await.
    prefix_awaited: Vec<(usize, bool)>,
    /// Offsets of every `PaginatedRequest` path segment in caller code.
    paginated_request_references: Vec<usize>,
    /// Offsets of `PaginatedRequest` annotations rewritten to a v3 terminal.
    rewritten_paginated_request: Vec<usize>,
    /// Terminal type names that rewritten single-segment annotations use.
    imported_terminals: Vec<&'static str>,
}

/// Whether a path names a Concord facade item, by declaration identity.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Identity {
    /// Resolves to the named item of a Concord crate.
    Concord,
    /// Resolves to another item (a local type, another crate's item, ...).
    Other,
    /// Not proved either way.
    Unknown,
}

fn peel(expression: &Expr) -> &Expr {
    match expression {
        Expr::Paren(paren) => peel(&paren.expr),
        Expr::Group(group) => peel(&group.expr),
        other => other,
    }
}

impl CallerVisitor<'_, '_> {
    fn span(&self, span: Span) -> Rng {
        let range = span.byte_range();
        (range.start + self.base)..(range.end + self.base)
    }

    fn range(&self, node: &impl ToTokens) -> Rng {
        let mut spans = node.to_token_stream().into_iter().map(|token| token.span());
        let Some(first) = spans.next() else {
            return self.base..self.base;
        };
        let last = spans.last().unwrap_or(first);
        self.span(first).start..self.span(last).end
    }

    fn text(&self, node: &impl ToTokens) -> String {
        self.source[self.range(node)].to_owned()
    }

    fn record(&mut self, result: Result<(), String>, offset: usize) {
        if let Err(error) = result {
            self.diagnostics
                .push(RawDiagnostic::new(Code::Internal, offset, error));
        }
    }

    fn bind(&mut self, name: String, receiver: Receiver) {
        if let Some(scope) = self.scopes.last_mut() {
            scope.names.insert(name, receiver);
            scope.id = fresh_bindings_id();
        }
    }

    /// The receiver bound to a local name: `None` when no local binding (and
    /// no opaque statement macro) is in the way, so the name denotes an item.
    ///
    /// As in rustc, an item of a block between the use and the binding (a
    /// `const`, `static`, unit or tuple struct, function, block `use` or a
    /// glob that may bring one) shadows the binding: the name is then that
    /// item, which the tool does not follow (unknown). In the binding's own
    /// block only items a `let` cannot shadow count.
    fn local(&self, name: &str) -> Option<Receiver> {
        let (position, receiver) =
            self.scopes
                .iter()
                .enumerate()
                .rev()
                .find_map(|(position, scope)| {
                    if let Some(receiver) = scope.names.get(name) {
                        Some((position, receiver.clone()))
                    } else {
                        scope.opaque.then(|| (position, Receiver::unknown()))
                    }
                })?;
        let model = &self.index.model;
        let shadowed =
            self.scopes[position..]
                .iter()
                .enumerate()
                .rev()
                .find_map(|(offset, scope)| {
                    let block = scope.block?;
                    let own_block = offset == 0 && scope.names.contains_key(name);
                    model.block_item_shadows(block, name, own_block)
                });
        Some(match shadowed {
            Some(reason) => Receiver::Unknown(Why::new(reason)),
            None => receiver,
        })
    }

    fn lookup(&self, name: &str) -> Receiver {
        self.local(name).unwrap_or(Receiver::unknown())
    }

    fn context(&self) -> Context<'_> {
        Context {
            scope: self.scope,
            generics: &self.generics,
            self_type: self.self_types.last(),
        }
    }

    fn receiver_for_type(&self, ty: &Type) -> Receiver {
        let (resolved, cause) = self.index.model.resolve_type_traced(self.context(), ty);
        Receiver::from_traced(resolved, cause)
    }

    /// Binds every name a pattern may bind to an unknown receiver, because
    /// the declaration binding it is gated by `#[cfg]`/`#[cfg_attr]` at
    /// `location` (it may not be compiled, so an outer binding may be seen).
    fn bind_gated(&mut self, pattern: &Pat, location: &str) {
        let mut names = Vec::new();
        if !pattern_names(pattern, &mut names) {
            self.hide_bindings();
            return;
        }
        for name in names {
            let why = Why::new(format!(
                "`{name}` is bound by a declaration gated by `#[cfg]`/`#[cfg_attr]` ({location}), which may not be compiled, so the binding the call sees is unknown"
            ));
            self.bind(name, Receiver::Unknown(why));
        }
    }

    /// `line N` of a span in this file.
    fn location(&self, span: Span) -> String {
        format!("line {}", span.start().line)
    }

    /// Whether `segments` (resolved in `scope`) name the Concord item `name`.
    fn concord_identity_in(
        &self,
        scope: Option<ScopeId>,
        leading_colon: bool,
        segments: &[String],
        name: &str,
    ) -> Identity {
        let context = Context {
            scope,
            generics: &self.generics,
            self_type: self.self_types.last(),
        };
        match self
            .index
            .model
            .resolve_type_segments(context, leading_colon, segments)
        {
            TypeRes::External(path)
                if path.first().is_some_and(|first| is_concord_crate(first))
                    && path.last().is_some_and(|last| last == name) =>
            {
                Identity::Concord
            }
            TypeRes::Unknown => Identity::Unknown,
            _ => Identity::Other,
        }
    }

    /// Whether the first `length` segments of `path`, resolved here, name the
    /// Concord item `name`.
    fn concord_identity(&self, path: &syn::Path, length: usize, name: &str) -> Identity {
        let segments = path
            .segments
            .iter()
            .take(length)
            .map(|segment| canonical(&segment.ident))
            .collect::<Vec<_>>();
        self.concord_identity_in(self.scope, path.leading_colon.is_some(), &segments, name)
    }

    /// `PageLimit::Prefix(n)` / `PageLimit::CompleteWithin(n)` whose
    /// `PageLimit` is proved to be Concord's (a local type with the same name
    /// is not).
    fn concord_page_limit<'e>(&self, argument: &'e Expr) -> Option<(PageLimitVariant, &'e Expr)> {
        let (variant, inner, path) = page_limit_constructor(argument)?;
        (self.concord_identity(path, path.segments.len() - 1, "PageLimit") == Identity::Concord)
            .then_some((variant, inner))
    }

    /// Where a method call dispatches and the value it produces.
    fn method_call(&self, call: &syn::ExprMethodCall) -> (Dispatch, Receiver) {
        self.method_call_rewriting(call, None)
    }

    /// [`Self::method_call`] for a call this tool would rename to `rewrite`:
    /// the proof also covers the new name (see [`Self::call`]).
    fn method_call_rewriting(
        &self,
        call: &syn::ExprMethodCall,
        rewrite: Option<&str>,
    ) -> (Dispatch, Receiver) {
        let key = (
            call.method.span().byte_range().start,
            rewrite.map(str::to_owned),
            self.scope,
            self.generics.len(),
            self.self_types.len(),
            self.scopes.iter().map(|layer| layer.id).collect::<Vec<_>>(),
        );
        if let Some(found) = self.memo.borrow().get(&key) {
            return found.clone();
        }
        let receiver = self.infer(&call.receiver);
        let arguments = call.args.iter().collect::<Vec<_>>();
        let (dispatch, result) =
            self.call(&receiver, &canonical(&call.method), &arguments, rewrite);
        let result = (self.in_every_mount(dispatch), result);
        self.memo.borrow_mut().insert(key, result.clone());
        result
    }

    /// A call proved to reach a generated method is proved for the first
    /// mount of this file only when the file is compiled more than once:
    /// unknown then, with that reason.
    fn in_every_mount(&self, dispatch: Dispatch) -> Dispatch {
        match (&self.mounted, dispatch) {
            (Some(reason), Dispatch::Generated(_)) => Dispatch::Unknown(Why::new(reason.clone())),
            (_, dispatch) => dispatch,
        }
    }

    /// Whether a `paginate` call provably reaches the generated traversal of
    /// a request (only a paginated endpoint's request has one).
    fn generated_paginate(dispatch: &Dispatch) -> bool {
        matches!(
            dispatch,
            Dispatch::Generated(owners)
                if !owners.is_empty() && owners.iter().all(|owner| owner.role == Role::Request)
        )
    }

    /// A `.paginate(PageLimit::X(n))` call this tool may rewrite: it is
    /// proved to reach the generated request's `paginate` and its `PageLimit`
    /// is Concord's. The terminal rewrite, the `.await` follow-up and the
    /// `PaginatedRequest` annotation all use this one decision.
    fn proved_paginate<'e>(
        &self,
        call: &'e syn::ExprMethodCall,
    ) -> Option<(PageLimitVariant, &'e Expr)> {
        if canonical(&call.method) != "paginate" || call.args.len() != 1 {
            return None;
        }
        let constructor = self.concord_page_limit(&call.args[0])?;
        let terminal = terminal_method(constructor.0);
        Self::generated_paginate(&self.method_call_rewriting(call, Some(terminal)).0)
            .then_some(constructor)
    }

    /// A proved `.paginate(PageLimit::Prefix(n))` call that is the direct
    /// base of `.await`.
    fn awaited_prefix<'e>(&self, expression: &'e Expr) -> Option<&'e syn::ExprMethodCall> {
        let Expr::Await(awaited) = peel(expression) else {
            return None;
        };
        self.prefix_call(&awaited.base)
    }

    /// A proved `.paginate(PageLimit::Prefix(n))` method call.
    fn prefix_call<'e>(&self, expression: &'e Expr) -> Option<&'e syn::ExprMethodCall> {
        let Expr::MethodCall(call) = peel(expression) else {
            return None;
        };
        matches!(
            self.proved_paginate(call),
            Some((PageLimitVariant::Prefix, _))
        )
        .then_some(call)
    }

    fn push_generics(&mut self, generics: &syn::Generics) -> usize {
        let before = self.generics.len();
        for parameter in &generics.params {
            if let syn::GenericParam::Type(parameter) = parameter {
                self.generics.push(canonical(&parameter.ident));
            }
        }
        before
    }

    /// Enters the scope anchored at `offset` in this file (an inline module
    /// name or a block's opening brace), returning the scope to restore. Code
    /// the crate model does not know resolves nothing.
    fn enter(&mut self, offset: usize) -> Option<ScopeId> {
        let entered = self
            .file
            .and_then(|file| self.index.model.anchor(file, offset));
        std::mem::replace(&mut self.scope, entered)
    }

    /// Binds a function's parameters (and `self`) in a fresh binding stack:
    /// a nested function item cannot capture the enclosing function's locals.
    fn enter_function(&mut self, signature: &syn::Signature) -> Vec<Bindings> {
        let saved = std::mem::replace(&mut self.scopes, vec![Bindings::default()]);
        for input in &signature.inputs {
            match input {
                syn::FnArg::Typed(typed) if attribute_effects(&typed.attrs).gated => {
                    let location = self.location(typed.colon_token.span);
                    self.bind_gated(&typed.pat, &location);
                }
                syn::FnArg::Typed(typed) => {
                    let receiver = self.receiver_for_type(&typed.ty);
                    self.bind_pattern(&typed.pat, receiver);
                }
                syn::FnArg::Receiver(receiver) if attribute_effects(&receiver.attrs).gated => {
                    let location = self.location(receiver.self_token.span);
                    self.bind(
                        "self".to_owned(),
                        Receiver::Unknown(Why::new(format!(
                            "`self` is declared gated by `#[cfg]`/`#[cfg_attr]` ({location})"
                        ))),
                    );
                }
                syn::FnArg::Receiver(receiver) => {
                    let self_type = || {
                        self.self_types
                            .last()
                            .cloned()
                            .map_or(Receiver::unknown(), Receiver::from_type)
                    };
                    // `&self` is a reference to the `impl` type, not a value.
                    let resolved = match &receiver.kind {
                        syn::ReceiverKind::Typed(_, ty) => self.receiver_for_type(ty),
                        syn::ReceiverKind::Value => self_type(),
                        syn::ReceiverKind::Reference(_, _, None) => {
                            Receiver::wrap(Wrapper::Ref, self_type())
                        }
                        syn::ReceiverKind::Reference(_, _, Some(_)) => {
                            Receiver::wrap(Wrapper::RefMut, self_type())
                        }
                        _ => Receiver::unknown(),
                    };
                    self.bind("self".to_owned(), resolved);
                }
            }
        }
        saved
    }

    /// A pattern macro may bind any name it is given (or, for a procedural
    /// macro, any name at all): every name visible here becomes unknown.
    fn hide_bindings(&mut self) {
        if let Some(scope) = self.scopes.last_mut() {
            scope.names.clear();
            scope.opaque = true;
            scope.id = fresh_bindings_id();
        }
    }

    fn bind_pattern(&mut self, pattern: &Pat, receiver: Receiver) {
        let gated = match pattern {
            Pat::Ident(ident) => Some((&ident.attrs, ident.ident.span())),
            Pat::Type(typed) => Some((&typed.attrs, typed.colon_token.span)),
            _ => None,
        };
        if let Some((attributes, span)) = gated {
            if attribute_effects(attributes).gated {
                let location = self.location(span);
                self.bind_gated(pattern, &location);
                return;
            }
        }
        match pattern {
            Pat::Ident(ident) => {
                // `ref name` binds a reference to the matched value.
                let receiver = match (&ident.by_ref, &ident.mutability) {
                    (Some(_), None) => Receiver::wrap(Wrapper::Ref, receiver),
                    (Some(_), Some(_)) => Receiver::wrap(Wrapper::RefMut, receiver),
                    (None, _) => receiver,
                };
                self.bind(ident.ident.to_string(), receiver);
                if let Some((_, subpattern)) = &ident.subpat {
                    self.bind_pattern(subpattern, Receiver::unknown());
                }
            }
            Pat::Macro(_) | Pat::Verbatim(_) => self.hide_bindings(),
            Pat::Guard(guard) => self.bind_pattern(&guard.pat, receiver),
            // A declared type always wins over the initializer's: the
            // annotation may coerce the value (to a trait object, through
            // `Deref`, ...). An annotation the model does not resolve exactly
            // makes the binding unknown; only a plain `_` constrains nothing.
            Pat::Type(typed) => {
                let receiver = match typed.ty.as_ref() {
                    Type::Infer(_) => receiver,
                    annotation => match self.receiver_for_type(annotation) {
                        Receiver::Unknown(why) if why.text().is_none() => {
                            Receiver::Unknown(Why::new(format!(
                                "the binding's type annotation `{}` is not resolved exactly to a type the tool models (a trait object, `impl` type, generic parameter, partially inferred `_` or alias it cannot expand), and a declared type decides the binding's type (the value may be coerced to it), so the receiver is unknown",
                                self.text(annotation)
                            )))
                        }
                        declared => declared,
                    },
                };
                self.bind_pattern(&typed.pat, receiver);
            }
            Pat::Reference(reference) => self.bind_pattern(&reference.pat, Receiver::unknown()),
            Pat::Tuple(tuple) => {
                for element in &tuple.elems {
                    self.bind_pattern(element, Receiver::unknown());
                }
            }
            Pat::TupleStruct(tuple) => {
                for element in &tuple.elems {
                    self.bind_pattern(element, Receiver::unknown());
                }
            }
            Pat::Struct(structure) => {
                for field in &structure.fields {
                    self.bind_pattern(&field.pat, Receiver::unknown());
                }
            }
            Pat::Slice(slice) => {
                for element in &slice.elems {
                    self.bind_pattern(element, Receiver::unknown());
                }
            }
            Pat::Or(alternatives) => {
                for case in &alternatives.cases {
                    self.bind_pattern(case, Receiver::unknown());
                }
            }
            Pat::Paren(paren) => self.bind_pattern(&paren.pat, receiver),
            _ => {}
        }
    }

    fn infer(&self, expression: &Expr) -> Receiver {
        match expression {
            Expr::Paren(paren) => self.infer(&paren.expr),
            Expr::Group(group) => self.infer(&group.expr),
            Expr::Reference(reference) => {
                let wrapper = if reference.mutability.is_some() {
                    Wrapper::RefMut
                } else {
                    Wrapper::Ref
                };
                Receiver::wrap(wrapper, self.infer(&reference.expr))
            }
            // `?` looks through `Option` and `Result` only.
            Expr::Try(attempt) => match self.infer(&attempt.expr) {
                Receiver::Wrapped(Wrapper::Option | Wrapper::Result, inner) => *inner,
                other => Receiver::Unknown(other.why()),
            },
            // `*` looks through a reference or smart pointer only.
            Expr::Unary(unary) if matches!(unary.op, syn::UnOp::Deref(_)) => {
                match self.infer(&unary.expr) {
                    Receiver::Wrapped(wrapper, inner) if wrapper.derefs() => *inner,
                    other => Receiver::Unknown(other.why()),
                }
            }
            Expr::Path(path) if path.qself.is_none() => match path.path.get_ident() {
                Some(ident) => self.lookup(&ident.to_string()),
                None => Receiver::unknown(),
            },
            // A field is typed through the declaration of the struct that
            // owns it, never by its member name alone. Field access
            // auto-derefs references and smart pointers.
            Expr::Field(field) => {
                let mut base = self.infer(&field.base);
                while let Receiver::Wrapped(wrapper, inner) = base {
                    base = if wrapper.derefs() {
                        *inner
                    } else {
                        Receiver::unknown()
                    };
                }
                match base {
                    Receiver::Struct(id) => {
                        let name = match &field.member {
                            syn::Member::Named(name) => canonical(name),
                            syn::Member::Unnamed(index) => index.index.to_string(),
                        };
                        let (resolved, cause) =
                            self.index.model.field_traced(id, &name, self.scope);
                        Receiver::from_traced(resolved, cause)
                    }
                    other => Receiver::Unknown(other.why()),
                }
            }
            Expr::Struct(literal) if literal.qself.is_none() => {
                match self
                    .index
                    .model
                    .resolve_type_path(self.context(), &literal.path)
                {
                    TypeRes::Struct(id) => Receiver::Struct(id),
                    _ => Receiver::unknown(),
                }
            }
            Expr::Call(call) => self.infer_call(call),
            Expr::MethodCall(call) => self.method_call(call).1,
            _ => Receiver::unknown(),
        }
    }

    /// A call's result: a crate-local function (or tuple-struct constructor)
    /// the path resolves to, or a generated constructor (`Client::builder()`,
    /// `Client::unbound()`, `ClientBuilder::new()`, and `Client::new()`,
    /// which returns a `Result` and exists only when v2.1 generates it) or
    /// Concord configuration constructor whose type path resolves to that
    /// item.
    fn infer_call(&self, call: &syn::ExprCall) -> Receiver {
        let Expr::Path(path) = call.func.as_ref() else {
            return Receiver::unknown();
        };
        if path.qself.is_some() {
            return Receiver::unknown();
        }
        if let Some(ident) = path.path.get_ident() {
            // A local closure or function pointer shadows function items.
            if self.local(&ident.to_string()).is_some() {
                return Receiver::unknown();
            }
        }
        let model = &self.index.model;
        let (result, cause) = model.call_result_traced(self.context(), &path.path);
        if let Some(result) = result {
            return Receiver::from_traced(result, cause);
        }
        let mut prefix = path.path.clone();
        let Some(function) = prefix.segments.pop().map(|segment| segment.ident) else {
            return Receiver::Unknown(Why::of(cause));
        };
        if prefix.segments.is_empty() {
            return Receiver::Unknown(Why::of(cause));
        }
        let function = canonical(&function);
        let (prefix_type, prefix_cause) = model.resolve_type_path_traced(self.context(), &prefix);
        match prefix_type {
            TypeRes::Unknown => Receiver::Unknown(Why::of(prefix_cause.or(cause))),
            TypeRes::Generated(owners) => {
                // Inherent associated functions take precedence over trait
                // functions of the same name.
                let mut results = Vec::new();
                for owner in &owners {
                    let result = match (owner.role, function.as_str()) {
                        (Role::Built, "builder") | (Role::Builder, "new") => OwnerRef {
                            role: Role::Builder,
                            ..*owner
                        },
                        (Role::Built, "unbound") => OwnerRef {
                            role: Role::Unbound,
                            ..*owner
                        },
                        (Role::Built, "new") if self.index.clients[owner.client].has_new => *owner,
                        _ => return Receiver::unknown(),
                    };
                    if !results.contains(&result) {
                        results.push(result);
                    }
                }
                if results.is_empty() {
                    Receiver::unknown()
                } else if function == "new" && results.iter().all(|owner| owner.role == Role::Built)
                {
                    Receiver::wrap(Wrapper::Result, Receiver::Owners(results))
                } else {
                    Receiver::Owners(results)
                }
            }
            TypeRes::External(external) => {
                match (
                    concord_config_builder(&external),
                    concord_config(&external),
                    function.as_str(),
                ) {
                    (Some(true), _, "new" | "default") | (_, Some(true), "builder") => {
                        Receiver::RuntimeConfig
                    }
                    (Some(false), _, "new" | "default") | (_, Some(false), "builder") => {
                        Receiver::HttpConfig
                    }
                    // A constructor of another crate's type: possibly that
                    // crate's generated client or builder.
                    _ if !is_std_or_concord(&external) => Receiver::Unknown(Why::new(format!(
                        "the receiver chain starts at `{}::{function}`, an associated function of another crate's type (possibly generated by that crate's `api!`), and calls across crates are never rewritten",
                        external.join("::")
                    ))),
                    // Other associated functions (even `Box::new`) can
                    // return anything.
                    _ => Receiver::unknown(),
                }
            }
            TypeRes::Struct(_) | TypeRes::Wrapped(..) | TypeRes::Foreign => Receiver::unknown(),
        }
    }

    /// The generated inherent method `method` of one owner, as v2.1 emits
    /// it (see [`DeclIndex::generated_method`]).
    fn generated_method(&self, owner: OwnerRef, method: &str) -> Option<Method> {
        self.index.generated_method(owner, method)
    }

    /// Whether a generated type implements `Clone` (the client, scope
    /// facades, the unbound tree, and an unbound endpoint without a body).
    fn clonable(&self, owner: OwnerRef) -> bool {
        match owner.role {
            Role::Built | Role::Unbound | Role::Scope | Role::UnboundScope => true,
            Role::Endpoint => !self.index.owner(owner).has_body,
            Role::Builder | Role::Request => false,
        }
    }

    /// How a probed receiver type is written, for diagnostics.
    fn spell(&self, ty: &TypeRes) -> String {
        match ty {
            TypeRes::Generated(owners) => owners
                .first()
                .map_or_else(|| "_".to_owned(), |owner| self.generated_name(*owner)),
            TypeRes::Wrapped(wrapper, inner) => {
                wrapper.spelling().replacen('_', &self.spell(inner), 1)
            }
            TypeRes::Struct(_) | TypeRes::Foreign | TypeRes::Unknown => "_".to_owned(),
            TypeRes::External(path) => path.join("::"),
        }
    }

    /// The v2.1 name of one generated type.
    fn generated_name(&self, owner: OwnerRef) -> String {
        let client = &self.index.clients[owner.client].name;
        let logical = to_pascal_case(&self.index.owner(owner).logical);
        match owner.role {
            Role::Builder => format!("{client}Builder"),
            Role::Built => client.clone(),
            Role::Unbound | Role::UnboundScope => format!("{logical}::Unbound"),
            Role::Scope | Role::Endpoint => logical,
            Role::Request => format!("{logical}Request"),
        }
    }

    /// The dispatch gate for a call that reaches the generated method only
    /// after an auto-deref or auto-ref step: `earlier` are the receiver types
    /// method resolution probes first (each by value, then by reference), and
    /// `names` the method's name and, for a rewrite, the new name (which must
    /// reach the generated method in v3 as well).
    ///
    /// The generated inherent method is proved to be selected only when no
    /// trait method of one of those names can be selected at an earlier step:
    /// the name is no standard trait method, the crate's trait
    /// implementations are all visible to the model (see
    /// [`CrateModel::incomplete`]), no trait of another crate may be in scope
    /// here (see [`CrateModel::foreign_traits`]), and no trait implemented in
    /// this crate provides the name for a probed type. Returns why not,
    /// otherwise `None`. (A call whose receiver reaches the generated method
    /// at the first probe step, `earlier` empty, never consults this gate:
    /// inherent methods win at that step.)
    fn intercepted(&self, earlier: &[TypeRes], names: &[&str]) -> Option<String> {
        if earlier.is_empty() {
            return None;
        }
        let method = names.first()?;
        let steps = earlier
            .iter()
            .map(|probed| self.spell(probed))
            .collect::<Vec<_>>()
            .join("`, `");
        let blocked = |detail: String| {
            Some(format!(
                "the call reaches the generated `{method}` only after an auto-deref or auto-ref step (method resolution first probes `{steps}`), where a trait method may be selected instead: {detail}"
            ))
        };
        if let Some(name) = names.iter().find(|name| std_trait_method(name)) {
            return blocked(format!(
                "`{name}` is also a standard-library trait method that may be selected first"
            ));
        }
        let model = &self.index.model;
        if let Some(reason) = model.incomplete(self.scope) {
            return blocked(reason);
        }
        if let Some(reason) = model.foreign_traits(self.scope, names) {
            return blocked(reason);
        }
        for name in names {
            for candidate in model.trait_receivers(name, self.scope) {
                let applies = match &candidate.receiver {
                    None => true,
                    Some(receiver) => earlier.iter().any(|probed| probed.may_equal(receiver)),
                };
                if applies {
                    let place = if candidate.library {
                        "in the package library"
                    } else {
                        "in this crate"
                    };
                    let location = &candidate.location;
                    let target = candidate.unresolved_self.as_ref().map_or_else(
                        || "a probed type".to_owned(),
                        |written| format!("{written}, which may be a probed type"),
                    );
                    return blocked(if candidate.foreign {
                        format!(
                            "the trait {} (not defined in this crate, so its provided methods are unknown) is implemented {place} ({location}) for {target} and may provide `{name}`",
                            candidate.trait_name
                        )
                    } else {
                        format!(
                            "the trait {} implemented {place} ({location}) may provide `{name}` for {target}",
                            candidate.trait_name
                        )
                    });
                }
            }
        }
        None
    }

    /// The result of a generated method on `owner`.
    fn next(&self, owner: OwnerRef, next: Next, arguments: &[&Expr]) -> Receiver {
        match next {
            Next::Same => Receiver::Owners(vec![owner]),
            Next::Owner(child) => Receiver::Owners(vec![child]),
            Next::Built => Receiver::wrap(
                Wrapper::Result,
                Receiver::Owners(vec![OwnerRef {
                    role: Role::Built,
                    ..owner
                }]),
            ),
            Next::Bound => match arguments.first().map(|argument| self.infer(argument)) {
                Some(Receiver::Owners(endpoints))
                    if endpoints.iter().all(|endpoint| {
                        endpoint.role == Role::Endpoint && endpoint.client == owner.client
                    }) =>
                {
                    Receiver::Owners(
                        endpoints
                            .into_iter()
                            .map(|endpoint| OwnerRef {
                                role: Role::Request,
                                ..endpoint
                            })
                            .collect(),
                    )
                }
                Some(other) => Receiver::Unknown(other.why()),
                None => Receiver::unknown(),
            },
            Next::Opaque => Receiver::unknown(),
        }
    }

    /// `receiver.clone()`: `Clone::clone` takes `&self`, so a by-value
    /// method of that name (from a trait, or an inherent `clone` the
    /// application added) is found first; the receiver's own type is probed
    /// before `&T`, so the dispatch gate applies.
    fn clone_of(&self, receiver: &Receiver) -> Receiver {
        let Some(own_type) = receiver.as_type() else {
            return Receiver::Unknown(receiver.why());
        };
        let clonable_owners = |owners: &[OwnerRef]| {
            owners.iter().all(|owner| self.clonable(*owner))
                && !self.index.model.user_inherent_method(owners, "clone")
        };
        let blocked = self.intercepted(std::slice::from_ref(&own_type), &["clone"]);
        if let Some(reason) = blocked {
            return Receiver::Unknown(Why::new(reason));
        }
        match receiver {
            Receiver::Owners(owners) if clonable_owners(owners) => receiver.clone(),
            Receiver::Wrapped(Wrapper::Ref, inner) => match &**inner {
                Receiver::Owners(owners) if clonable_owners(owners) => (**inner).clone(),
                _ => Receiver::unknown(),
            },
            Receiver::Wrapped(
                Wrapper::Option | Wrapper::Result | Wrapper::Box | Wrapper::Arc | Wrapper::Rc,
                _,
            ) => receiver.clone(),
            _ => Receiver::unknown(),
        }
    }

    /// Where `receiver.method(arguments)` dispatches and what it produces.
    /// `rewrite` is the name this tool would give the call (`replace_x`,
    /// `collect_prefix`, ...): the proof must hold for it too.
    ///
    /// `Option`/`Result` are looked through only by `unwrap()`/`expect(..)`.
    /// Otherwise the receiver is auto-dereferenced through references and
    /// smart pointers to a generated type, whose generated inherent method
    /// must exist, be callable there (a `self` method only through a `Box`),
    /// and pass the dispatch gate ([`Self::intercepted`]) when a trait method
    /// could be selected at an earlier probe step.
    fn call(
        &self,
        receiver: &Receiver,
        method: &str,
        arguments: &[&Expr],
        rewrite: Option<&str>,
    ) -> (Dispatch, Receiver) {
        if let Receiver::Wrapped(wrapper @ (Wrapper::Option | Wrapper::Result), inner) = receiver {
            let unwrap = matches!((method, arguments.len()), ("unwrap", 0) | ("expect", 1));
            if unwrap {
                return (
                    Dispatch::Elsewhere(format!("a method of `{}`", wrapper.spelling())),
                    (**inner).clone(),
                );
            }
        }
        if method == "clone" && arguments.is_empty() {
            return (
                Dispatch::Elsewhere("`Clone::clone`".to_owned()),
                self.clone_of(receiver),
            );
        }
        match receiver {
            Receiver::RuntimeConfig | Receiver::HttpConfig => {
                let methods = if matches!(receiver, Receiver::RuntimeConfig) {
                    RUNTIME_CONFIG_METHODS
                } else {
                    HTTP_CONFIG_METHODS
                };
                return if methods.contains(&method) {
                    (Dispatch::Config, receiver.clone())
                } else {
                    (Dispatch::unknown(), Receiver::unknown())
                };
            }
            Receiver::Unknown(why) => {
                return (
                    Dispatch::Unknown(why.clone()),
                    Receiver::Unknown(why.clone()),
                );
            }
            _ => {}
        }
        // Auto-deref to the generated value.
        let mut layers = Vec::new();
        let mut current = receiver;
        let owners = loop {
            match current {
                Receiver::Owners(owners) => break owners,
                Receiver::Wrapped(wrapper, inner) if wrapper.derefs() => {
                    layers.push((*wrapper, current));
                    current = inner;
                }
                Receiver::Wrapped(wrapper, _) => {
                    return (
                        Dispatch::Elsewhere(format!(
                            "the receiver is `{}` around the value, which has no generated methods (the call is a method of the wrapper or of a trait); unwrap it explicitly (`?`, `.unwrap()`, `.expect(..)`) if the generated value is meant",
                            wrapper.spelling()
                        )),
                        Receiver::unknown(),
                    );
                }
                Receiver::Unknown(why) => {
                    return (
                        Dispatch::Unknown(why.clone()),
                        Receiver::Unknown(why.clone()),
                    );
                }
                Receiver::External(path) => {
                    let path = path.join("::");
                    return (
                        Dispatch::Elsewhere(format!(
                            "the receiver resolves to `{path}`, a type of another crate (possibly generated by that crate's `api!` declarations), and calls across crates are never rewritten"
                        )),
                        Receiver::Unknown(Why::new(format!(
                            "the receiver chain starts at `{path}`, a type of another crate (possibly generated by that crate's `api!` declarations), and calls across crates are never rewritten"
                        ))),
                    );
                }
                Receiver::Struct(_)
                | Receiver::Foreign
                | Receiver::RuntimeConfig
                | Receiver::HttpConfig => {
                    return (
                        Dispatch::Elsewhere(NOT_GENERATED.to_owned()),
                        Receiver::unknown(),
                    );
                }
            }
        };
        let Some(methods) = owners
            .iter()
            .map(|owner| self.generated_method(*owner, method))
            .collect::<Option<Vec<_>>>()
        else {
            return if owners
                .iter()
                .all(|owner| self.generated_method(*owner, method).is_none())
            {
                (Dispatch::Undefined, Receiver::unknown())
            } else {
                (Dispatch::unknown(), Receiver::unknown())
            };
        };
        let by_ref = methods.first().is_some_and(|method| method.by_ref);
        if methods.iter().any(|method| method.by_ref != by_ref) {
            return (Dispatch::unknown(), Receiver::unknown());
        }
        if !by_ref {
            if let Some((wrapper, _)) = layers.iter().find(|(wrapper, _)| !wrapper.moves_out()) {
                return (
                    Dispatch::Elsewhere(format!(
                        "the receiver is `{}` around the value, and the generated method takes `self` by value, which cannot be moved out of it (the call resolves to a trait method)",
                        wrapper.spelling()
                    )),
                    Receiver::unknown(),
                );
            }
        }
        // The receiver types probed before the inherent method is found.
        let generated = TypeRes::Generated(owners.clone());
        let target = if by_ref {
            TypeRes::wrap(Wrapper::Ref, generated.clone())
        } else {
            generated.clone()
        };
        let mut earlier = Vec::new();
        let mut reached = false;
        'layers: for (_, layer) in &layers {
            let Some(probed) = layer.as_type() else {
                return (Dispatch::unknown(), Receiver::unknown());
            };
            for candidate in [
                probed.clone(),
                TypeRes::wrap(Wrapper::Ref, probed.clone()),
                TypeRes::wrap(Wrapper::RefMut, probed),
            ] {
                if candidate == target {
                    reached = true;
                    break 'layers;
                }
                earlier.push(candidate);
            }
        }
        if !reached && by_ref {
            earlier.push(generated);
        }
        let mut names = vec![method];
        names.extend(rewrite);
        if let Some(reason) = self.intercepted(&earlier, &names) {
            let why = Why::new(reason);
            return (Dispatch::Unknown(why.clone()), Receiver::Unknown(why));
        }
        let mut results = Vec::new();
        for (owner, found) in owners.iter().zip(&methods) {
            match self.next(*owner, found.next, arguments) {
                Receiver::Owners(next) => {
                    for next in next {
                        if !results.contains(&next) {
                            results.push(next);
                        }
                    }
                }
                other if owners.len() == 1 => {
                    return (Dispatch::Generated(owners.clone()), other);
                }
                _ => return (Dispatch::Generated(owners.clone()), Receiver::unknown()),
            }
        }
        (
            Dispatch::Generated(owners.clone()),
            Receiver::Owners(results),
        )
    }

    /// Where a fully qualified call `Type::method(receiver, ..)` dispatches:
    /// an inherent associated function of the type is found before a trait's.
    fn qualified_call(&self, receiver: &Receiver, method: &str) -> Dispatch {
        match receiver {
            Receiver::Owners(owners) => {
                let found = owners
                    .iter()
                    .filter(|owner| self.generated_method(**owner, method).is_some())
                    .count();
                if found == owners.len() {
                    Dispatch::Generated(owners.clone())
                } else if found == 0 {
                    Dispatch::Undefined
                } else {
                    Dispatch::unknown()
                }
            }
            Receiver::RuntimeConfig | Receiver::HttpConfig => Dispatch::Config,
            Receiver::Wrapped(wrapper, _) => Dispatch::Elsewhere(format!(
                "the qualified type is `{}` around the value, which has no generated methods",
                wrapper.spelling()
            )),
            Receiver::External(path) => Dispatch::Elsewhere(format!(
                "the qualified type resolves to `{}`, a type of another crate (possibly generated by that crate's `api!` declarations), and calls across crates are never rewritten",
                path.join("::")
            )),
            Receiver::Struct(_) | Receiver::Foreign => {
                Dispatch::Elsewhere(NOT_GENERATED.to_owned())
            }
            Receiver::Unknown(why) => Dispatch::Unknown(why.clone()),
        }
    }

    fn value_optionality(&self, owner: OwnerRef, value: &str) -> Option<bool> {
        match owner.role {
            Role::Builder | Role::Scope | Role::UnboundScope | Role::Request | Role::Endpoint => {
                self.index
                    .owner(owner)
                    .values
                    .iter()
                    .find(|(name, _)| name == value)
                    .map(|(_, optional)| *optional)
            }
            Role::Built | Role::Unbound => None,
        }
    }

    fn check_method(&mut self, node: &syn::ExprMethodCall) {
        // A raw identifier (`r#set_x`) names the same method.
        let method = canonical(&node.method);
        self.shadow_method(node, &method);
        self.removed_method(node, &method);
        // Every `set_*` spelling is a candidate: whether it is a generated
        // setter is decided by the v2.1 declared values and their generated
        // method roles (v2.1 generated no conditional `set_*_if_some`, so
        // `set_x_if_some` is the exact setter of a declared `x_if_some`, and
        // otherwise not a generated method), never by the name's suffix.
        if let Some(value) = method.strip_prefix("set_") {
            if node.args.len() == 1 && !value.is_empty() {
                self.setter(node, value);
            }
            return;
        }
        if !self.concord_file {
            return;
        }
        if method == "paginate" && node.args.len() == 1 {
            self.paginate(node);
            return;
        }
        if NONZERO_RUNTIME_SETTERS.contains(&method.as_str()) && node.args.len() == 1 {
            self.nonzero(node, &method);
            return;
        }
        if let Some(credential) = method.strip_prefix("store_as_") {
            if node.args.is_empty() && self.index.has_endpoint_credential(credential) {
                let receiver = self.text(&*node.receiver);
                self.diagnostics.push(
                    RawDiagnostic::new(
                        Code::StoreOutcome,
                        self.span(node.method.span()).start,
                        format!(
                            "`{method}()` now resolves to `StoreOutcome`: a newer explicit installation intent supersedes this one and the produced material is dropped; the application must decide what `Superseded` means"
                        ),
                    )
                    .suggest(format!(
                        "match {receiver}.{method}().await? {{ StoreOutcome::Installed {{ version }} => {{ .. }}, StoreOutcome::Superseded => {{ .. }} }}"
                    )),
                );
            }
        }
    }

    fn setter(&mut self, node: &syn::ExprMethodCall, value: &str) {
        let replacement = format!("replace_{value}");
        let (dispatch, _) = self.method_call_rewriting(node, Some(&replacement));
        let argument = self.text(&node.args[0]);
        self.migrate_setter(
            &node.method,
            value,
            dispatch,
            format!(".{}({argument})", renamed(&node.method, &replacement)),
        );
    }

    /// Fully qualified setter calls: `api::ItemRequest::set_x(request, value)`
    /// and `<api::ItemRequest>::set_x(request, value)`. The type path is
    /// resolved like any other; a trait-qualified call is never proved.
    fn ufcs_setter(&mut self, node: &syn::ExprCall) {
        let Expr::Path(path) = node.func.as_ref() else {
            return;
        };
        let segments = &path.path.segments;
        if node.args.len() != 2 {
            return;
        }
        let Some(method) = segments.last().map(|segment| &segment.ident) else {
            return;
        };
        let method_name = canonical(method);
        let Some(value) = method_name.strip_prefix("set_") else {
            return;
        };
        if value.is_empty() {
            return;
        }
        let receiver = match &path.qself {
            Some(qself) if qself.position == 0 && segments.len() == 1 => {
                self.receiver_for_type(&qself.ty)
            }
            Some(_) => Receiver::unknown(),
            None if segments.len() < 2 => return,
            None => {
                let mut prefix = path.path.clone();
                prefix.segments.pop();
                let (resolved, cause) = self
                    .index
                    .model
                    .resolve_type_path_traced(self.context(), &prefix);
                Receiver::from_traced(resolved, cause)
            }
        };
        let function = self.text(&*node.func);
        let written = method.to_string();
        let qualifier = function
            .strip_suffix(written.as_str())
            .unwrap_or(function.as_str());
        let suggestion = format!(
            "{qualifier}{}({}, {})",
            renamed(method, &format!("replace_{value}")),
            self.text(&node.args[0]),
            self.text(&node.args[1])
        );
        let dispatch = self.in_every_mount(self.qualified_call(&receiver, &method_name));
        self.migrate_setter(method, value, dispatch, suggestion);
    }

    /// A generated setter named as a function value, not called:
    /// `api::ItemRequest::set_x` passed to `fold`, bound to a variable,
    /// `Self::set_x`, `<api::ItemRequest>::set_x`. A value keeps its v2.1
    /// meaning only under the v3 name `replace_x`, and the v3 `set_x` may
    /// accept the same arguments with another meaning, so it is reported when
    /// the path resolves to a generated optional setter or cannot be resolved
    /// to an item that is not generated; it is never rewritten. A path whose
    /// type is proved not to be generated, and a trait-qualified path
    /// (`<T as Trait>::set_x`, never a generated inherent setter), are not.
    fn setter_value(&mut self, node: &syn::ExprPath) {
        let segments = &node.path.segments;
        let Some(method) = segments.last().map(|segment| &segment.ident) else {
            return;
        };
        let method_name = canonical(method);
        let Some(value) = method_name.strip_prefix("set_") else {
            return;
        };
        if value.is_empty() {
            return;
        }
        let Some(owner) = self.index.optional_value_owner(value) else {
            return;
        };
        let receiver = match &node.qself {
            Some(qself) if qself.position == 0 && segments.len() == 1 => {
                self.receiver_for_type(&qself.ty)
            }
            Some(_) => return,
            None if segments.len() < 2 => return,
            None => {
                let mut prefix = node.path.clone();
                prefix.segments.pop();
                let (resolved, cause) = self
                    .index
                    .model
                    .resolve_type_path_traced(self.context(), &prefix);
                Receiver::from_traced(resolved, cause)
            }
        };
        let detail = match self.qualified_call(&receiver, &method_name) {
            Dispatch::Generated(owners) => {
                let optional = owners
                    .iter()
                    .any(|owner| self.value_optionality(*owner, value) == Some(true));
                if !optional {
                    return;
                }
                "it resolves to the generated optional setter".to_owned()
            }
            Dispatch::Undefined | Dispatch::Config => return,
            Dispatch::Elsewhere(reason) => match receiver {
                Receiver::External(_) => reason,
                _ => return,
            },
            Dispatch::Unknown(why) => why.text().map_or_else(
                || "its type could not be resolved to a type that is not generated".to_owned(),
                str::to_owned,
            ),
        };
        let path = self.text(node);
        let written = method.to_string();
        let qualifier = path.strip_suffix(written.as_str()).unwrap_or(path.as_str());
        let offset = self.span(method.span()).start;
        self.diagnostics.push(
            RawDiagnostic::new(
                Code::SetterUnresolved,
                offset,
                format!(
                    "`set_{value}` may target a Concord-optional value `{value}` declared {owner}, but the setter is used as a function value (`{path}` is not called here), which the tool never rewrites ({detail}); the path was left unchanged. If it is the optional value, v2.1 exact replacement is `replace_{value}`"
                ),
            )
            .suggest(format!(
                "{qualifier}{}",
                renamed(method, &format!("replace_{value}"))
            )),
        );
    }

    /// Whether a call of `name` may be a v3-only generated method of this
    /// crate or of another crate of the run (a cheap filter).
    fn may_shadow(&self, name: &str) -> bool {
        self.index.v3_names.iter().any(|known| known == name)
            || self
                .index
                .other_crate_v3_names
                .iter()
                .any(|(known, _)| known == name)
    }

    /// The v3-only generated methods named `name` (taking `arity` arguments
    /// besides the receiver, when known) of the generated types `owners`.
    fn v3_hits(
        &self,
        owners: &[OwnerRef],
        name: &str,
        arity: Option<usize>,
    ) -> Vec<(OwnerRef, V3Name)> {
        owners
            .iter()
            .flat_map(|owner| {
                self.index
                    .v3_only(*owner)
                    .into_iter()
                    .filter(|candidate| {
                        candidate.name == name && arity.is_none_or(|arity| arity == candidate.arity)
                    })
                    .map(|candidate| (*owner, candidate))
            })
            .collect()
    }

    /// The generated types of this crate that a call of `name` on an unknown
    /// receiver may reach in v3 only. A value control (`replace_x`,
    /// `set_x_if_some`) names a declared value and counts crate-wide; a core
    /// method (`bind`, `pages`, ...) counts only in a file that uses Concord,
    /// as `.paginate(..)` does.
    fn crate_hits(&self, name: &str, arity: Option<usize>) -> Vec<(OwnerRef, V3Name)> {
        self.v3_hits(&self.index.generated_types(), name, arity)
            .into_iter()
            .filter(|(owner, candidate)| {
                self.concord_file
                    || self
                        .index
                        .owner(*owner)
                        .v3_values
                        .iter()
                        .any(|value| value.name == candidate.name)
            })
            .collect()
    }

    /// Whether a call of `name` on `receiver` may reach, in v3, an inherent
    /// method the v3 generator defines and v2.1 did not.
    fn shadow(&self, receiver: &Receiver, name: &str, arity: Option<usize>) -> Shadow {
        self.shadow_through(receiver, name, arity, true)
    }

    /// [`Self::shadow`] after auto-deref steps: `movable` while every step
    /// was a `Box` (a `self` method is reachable only then; a `&self` one
    /// through any reference or smart pointer).
    fn shadow_through(
        &self,
        receiver: &Receiver,
        name: &str,
        arity: Option<usize>,
        movable: bool,
    ) -> Shadow {
        let reachable = |hits: Vec<(OwnerRef, V3Name)>| {
            hits.into_iter()
                .filter(|(_, candidate)| movable || candidate.by_ref)
                .collect::<Vec<_>>()
        };
        match receiver {
            Receiver::Owners(owners) => {
                let hits = reachable(self.v3_hits(owners, name, arity));
                if hits.is_empty() {
                    Shadow::None
                } else {
                    Shadow::Proved(hits)
                }
            }
            // Auto-deref reaches the generated type's inherent methods.
            Receiver::Wrapped(wrapper, inner) if wrapper.derefs() => {
                self.shadow_through(inner, name, arity, movable && wrapper.moves_out())
            }
            Receiver::Unknown(why) => {
                let why = why.text().unwrap_or(UNPROVED_SHADOW).to_owned();
                let hits = self.crate_hits(name, arity);
                if !hits.is_empty() {
                    Shadow::Maybe(hits, why)
                } else if self
                    .index
                    .other_crate_v3_values
                    .iter()
                    .any(|known| known == name)
                {
                    Shadow::OtherCrate(why)
                } else {
                    Shadow::None
                }
            }
            Receiver::External(path)
                if self
                    .index
                    .other_crate_v3_names
                    .iter()
                    .any(|(known, taken)| {
                        known == name && arity.is_none_or(|arity| arity == *taken)
                    }) =>
            {
                Shadow::External(path.join("::"))
            }
            // `Option`/`Result`, crate-local structs, configuration builders
            // and types proved not to be generated have no generated methods.
            _ => Shadow::None,
        }
    }

    /// The application trait methods named `name` that the crate implements
    /// for `owners` (for any generated type when empty), for diagnostics.
    fn shadowed_traits(&self, name: &str, owners: &[OwnerRef]) -> String {
        let target = TypeRes::Generated(owners.to_vec());
        let mut found = Vec::new();
        for candidate in self.index.model.trait_receivers(name, self.scope) {
            let applies = match &candidate.receiver {
                None => true,
                Some(receiver) => {
                    let mut inner = receiver;
                    while let TypeRes::Wrapped(Wrapper::Ref | Wrapper::RefMut, next) = inner {
                        inner = next;
                    }
                    owners.is_empty() || inner.may_equal(&target)
                }
            };
            let text = format!(
                "{} (implemented at {})",
                candidate.trait_name, candidate.location
            );
            if applies && !found.contains(&text) {
                found.push(text);
            }
        }
        if found.is_empty() {
            "a trait method of that name the tool does not see (a trait of another crate, or one a macro implements)".to_owned()
        } else {
            format!("the trait method of {}", found.join(", "))
        }
    }

    /// Reports a call (or function value) `form` of `name` at `offset` that
    /// may reach a v3-only generated method: it is never rewritten.
    fn report_shadow(&mut self, offset: usize, name: &str, shadow: Shadow, form: &str) {
        let advice = format!(
            "It was left unchanged; migrate it by hand: call the application's method explicitly (`Trait::{name}(receiver, ..)`) or rename it"
        );
        let message = match shadow {
            Shadow::None => return,
            Shadow::Proved(hits) => {
                let owners = hits.iter().map(|(owner, _)| *owner).collect::<Vec<_>>();
                let ty = self.generated_name(owners[0]);
                let mut what = hits
                    .iter()
                    .map(|(_, candidate)| candidate.what.clone())
                    .collect::<Vec<_>>();
                what.dedup();
                format!(
                    "`{name}` is not a method v2.1 generates for `{ty}`, so in v2.1 {form} reached an application method: {}. v3 generates `{name}` on `{ty}` as {}, an inherent method, and an inherent method takes precedence over a trait method of the same name, so {form} would silently call the generated method in v3. {advice}",
                    self.shadowed_traits(name, &owners),
                    what.join(" and ")
                )
            }
            Shadow::Maybe(hits, why) => {
                let mut types = Vec::new();
                for (owner, candidate) in &hits {
                    let text = format!("`{}` ({})", self.generated_name(*owner), candidate.what);
                    if !types.contains(&text) {
                        types.push(text);
                    }
                }
                format!(
                    "{form} may reach a generated type of this crate on which v3 generates `{name}` as an inherent method that v2.1 did not generate ({}), but {why}. If the receiver is such a type, v2.1 called an application method ({}) and v3 would silently call the generated method instead, because an inherent method takes precedence over a trait method of the same name. {advice}",
                    types.join("; "),
                    self.shadowed_traits(name, &[])
                )
            }
            Shadow::OtherCrate(why) => format!(
                "{form} may reach a generated type of another crate of this migration run on which v3 generates `{name}` as a value control that v2.1 did not generate, but {why}. If the receiver is such a type, v2.1 called an application method and v3 would silently call the generated method instead, because an inherent method takes precedence over a trait method of the same name. {advice}"
            ),
            Shadow::External(path) => format!(
                "{form} has a receiver of type `{path}`, a type of another crate, and another crate of this migration run generates `{name}` in v3 as an inherent method that v2.1 did not generate: if `{path}` is such a generated type, v2.1 called an application method and v3 would silently call the generated method instead. {advice}"
            ),
        };
        self.diagnostics.push(RawDiagnostic::new(
            Code::GeneratedNameShadow,
            offset,
            message,
        ));
    }

    /// `receiver.name(..)` (see [`Self::shadow`]).
    fn shadow_method(&mut self, node: &syn::ExprMethodCall, name: &str) {
        if !self.may_shadow(name) {
            return;
        }
        let receiver = self.infer(&node.receiver);
        let shadow = self.shadow(&receiver, name, Some(node.args.len()));
        let offset = self.span(node.method.span()).start;
        self.report_shadow(offset, name, shadow, "this call");
    }

    /// `Type::name(receiver, ..)` (`arguments` holds the argument count) or
    /// the function value `Type::name`: a type-qualified path finds an
    /// inherent associated function before a trait's; a trait-qualified path
    /// (`Trait::name`, `<T as Trait>::name`) names the trait's method.
    fn shadow_path(&mut self, node: &syn::ExprPath, arguments: Option<usize>) {
        let segments = &node.path.segments;
        let Some(method) = segments.last().map(|segment| &segment.ident) else {
            return;
        };
        let name = canonical(method);
        if !self.may_shadow(&name) {
            return;
        }
        let receiver = match &node.qself {
            Some(qself) if qself.position == 0 && segments.len() == 1 => {
                self.receiver_for_type(&qself.ty)
            }
            Some(_) => return,
            None if segments.len() < 2 => return,
            None => {
                let mut prefix = node.path.clone();
                prefix.segments.pop();
                let (resolved, cause) = self
                    .index
                    .model
                    .resolve_type_path_traced(self.context(), &prefix);
                Receiver::from_traced(resolved, cause)
            }
        };
        let arity = match arguments {
            Some(0) => return,
            Some(count) => Some(count - 1),
            None => None,
        };
        let form = match arguments {
            Some(_) => "this type-qualified call".to_owned(),
            None => format!("the function value `{}`", self.text(node)),
        };
        // A qualified path names the type itself: a wrapper has no generated
        // associated functions.
        let shadow = match receiver {
            Receiver::Wrapped(..) => Shadow::None,
            receiver => self.shadow(&receiver, &name, arity),
        };
        let offset = self.span(method.span()).start;
        self.report_shadow(offset, &name, shadow, &form);
    }

    /// A call of `name` inside a macro the tool does not expand: its
    /// receiver is unknown.
    fn shadow_in_macro(&mut self, name: &str, offset: usize, context: &str) {
        if !self.may_shadow(name) {
            return;
        }
        let why = format!(
            "it is inside {context}, which the tool does not expand (the macro may use the tokens in any way)"
        );
        let shadow = self.shadow(&Receiver::Unknown(Why::new(why)), name, None);
        self.report_shadow(offset, name, shadow, "this call");
    }

    /// Whether a call of `name` may be a removed generated method of this
    /// crate or of another crate of the run whose callers are reported for a
    /// manual decision (a cheap filter; `paginate` is the paginate rule's).
    fn may_be_removed(&self, name: &str) -> bool {
        self.index.removed_names.iter().any(|known| known == name)
            || self
                .index
                .other_crate_removed_names
                .iter()
                .any(|(known, _)| known == name)
    }

    /// The removed generated methods named `name` (taking `arity` arguments
    /// besides the receiver, when known) of the generated types `owners`.
    fn removed_hits(
        &self,
        owners: &[OwnerRef],
        name: &str,
        arity: Option<usize>,
    ) -> Vec<(OwnerRef, RemovedName)> {
        owners
            .iter()
            .flat_map(|owner| {
                self.index
                    .v3_removed(*owner)
                    .into_iter()
                    .filter(|candidate| {
                        candidate.name == name && arity.is_none_or(|arity| arity == candidate.arity)
                    })
                    .map(|candidate| (*owner, candidate))
            })
            .collect()
    }

    /// Whether a call of `name` whose v2.1 dispatch is `dispatch` (on
    /// `receiver`) reached a generated method that v3 removed. An unknown
    /// receiver counts only in a file that uses Concord, as for a core
    /// v3-only name or `.paginate(..)`.
    fn removal(
        &self,
        dispatch: &Dispatch,
        receiver: &Receiver,
        name: &str,
        arity: Option<usize>,
    ) -> Removal {
        match dispatch {
            Dispatch::Generated(owners) => {
                let hits = self.removed_hits(owners, name, arity);
                if hits.is_empty() {
                    Removal::None
                } else {
                    Removal::Proved(hits)
                }
            }
            Dispatch::Unknown(why) if self.concord_file => {
                let hits = self.removed_hits(&self.index.generated_types(), name, arity);
                if hits.is_empty() {
                    Removal::None
                } else {
                    Removal::Maybe(hits, why.text().unwrap_or(UNPROVED_SHADOW).to_owned())
                }
            }
            Dispatch::Elsewhere(_) => {
                let mut current = receiver;
                while let Receiver::Wrapped(wrapper, inner) = current {
                    if !wrapper.derefs() {
                        return Removal::None;
                    }
                    current = inner;
                }
                match current {
                    Receiver::External(path)
                        if self
                            .index
                            .other_crate_removed_names
                            .iter()
                            .any(|(known, taken)| {
                                known == name && arity.is_none_or(|arity| arity == *taken)
                            }) =>
                    {
                        Removal::External(path.join("::"))
                    }
                    _ => Removal::None,
                }
            }
            Dispatch::Unknown(_) | Dispatch::Undefined | Dispatch::Config => Removal::None,
        }
    }

    /// Reports a call (or function value) `form` of `name` at `offset` that
    /// may have reached a generated method v3 removed with a manual-decision
    /// disposition: it is never rewritten. `spell` is the text around the v3
    /// name in a suggested hand rename (`(".", "(args)")`, `("Type::", "")`).
    fn report_removed(
        &mut self,
        offset: usize,
        name: &str,
        removal: Removal,
        form: &str,
        spell: (&str, &str),
    ) {
        let review = format!(
            "It was left unchanged. Review it: remove the call or replace it with the v3 form named here; if the application's trait method is really meant, call it explicitly (`Trait::{name}(receiver, ..)`), which names the same method in both versions."
        );
        let advice = |hits: &[(OwnerRef, RemovedName)]| {
            let mut texts = Vec::<&str>::new();
            for (_, removed) in hits {
                if !removed.advice.is_empty() && !texts.contains(&removed.advice.as_str()) {
                    texts.push(&removed.advice);
                }
            }
            texts.join(" ")
        };
        let (message, v3_name) = match removal {
            Removal::None => return,
            Removal::Proved(hits) => {
                let owners = hits.iter().map(|(owner, _)| *owner).collect::<Vec<_>>();
                let (owner, removed) = &hits[0];
                let ty = self.generated_name(*owner);
                (
                    format!(
                        "`{name}` is a method v2.1 generates on the {} `{ty}` ({}), so in v2.1 {form} called that generated inherent method. v3 no longer generates `{name}` there: `{ty}` has no inherent method of that name in v3, so {form}, left unchanged, no longer reaches Concord. It fails to compile unless an application trait in scope provides a `{name}` method for the type ({}); v3 then silently calls that trait method instead, because method resolution selects a trait method once no inherent method of that name exists. {} {review}",
                        role_label(owner.role),
                        removed.what,
                        self.shadowed_traits(name, &owners),
                        advice(&hits),
                    ),
                    removed.v3_name.clone(),
                )
            }
            Removal::Maybe(hits, why) => {
                // Grouped by role and member: `debug` is on every request.
                let mut groups = Vec::<(&'static str, String, Vec<String>)>::new();
                for (owner, removed) in &hits {
                    let role = role_label(owner.role);
                    let ty = format!("`{}`", self.generated_name(*owner));
                    match groups
                        .iter_mut()
                        .find(|(known, what, _)| *known == role && *what == removed.what)
                    {
                        Some((_, _, types)) => {
                            if !types.contains(&ty) {
                                types.push(ty);
                            }
                        }
                        None => groups.push((role, removed.what.clone(), vec![ty])),
                    }
                }
                let types = groups
                    .iter()
                    .map(|(role, what, types)| match types.as_slice() {
                        [only] => format!("the {role} {only} ({what})"),
                        types if types.len() <= 3 => {
                            format!("the {role} types {} ({what})", types.join(", "))
                        }
                        types => format!(
                            "{} {role} types of this crate, such as {} ({what})",
                            types.len(),
                            types[..3].join(", ")
                        ),
                    })
                    .collect::<Vec<_>>();
                (
                    format!(
                        "{form} may reach a generated type of this crate on which v2.1 generated `{name}` and v3 does not ({}), but {why}. If the receiver is such a type, v2.1 called the generated inherent method, and v3 has no inherent method of that name: the unchanged call fails to compile unless an application trait in scope provides `{name}` for it, which v3 would then call silently. {} {review}",
                        types.join("; "),
                        advice(&hits),
                    ),
                    hits[0].1.v3_name.clone(),
                )
            }
            Removal::External(path) => (
                format!(
                    "{form} has a receiver of type `{path}`, a type of another crate, and another crate of this migration run generated `{name}` in v2.1 on a generated type that v3 no longer generates it on: if `{path}` is such a type, v2.1 called the generated inherent method, and in v3 the unchanged call fails to compile or silently calls an application trait method of that name. {review}"
                ),
                None,
            ),
        };
        let mut diagnostic = RawDiagnostic::new(Code::GeneratedMemberRemoved, offset, message);
        if let Some(v3_name) = v3_name {
            diagnostic = diagnostic.suggest(format!("{}{v3_name}{}", spell.0, spell.1));
        }
        self.diagnostics.push(diagnostic);
    }

    /// `receiver.name(..)` of a removed generated method (see
    /// [`Self::removal`]). `paginate` is left to the paginate rule.
    fn removed_method(&mut self, node: &syn::ExprMethodCall, name: &str) {
        if !self.may_be_removed(name) {
            return;
        }
        let receiver = self.infer(&node.receiver);
        let (dispatch, _) = self.method_call(node);
        let removal = self
            .removal(&dispatch, &receiver, name, Some(node.args.len()))
            .manual();
        let arguments = node
            .args
            .iter()
            .map(|argument| self.text(argument))
            .collect::<Vec<_>>()
            .join(", ");
        let offset = self.span(node.method.span()).start;
        self.report_removed(
            offset,
            name,
            removal,
            "this call",
            (".", &format!("({arguments})")),
        );
    }

    /// `Type::name(receiver, ..)` (`arguments` holds the argument count) or
    /// the function value `Type::name` of a removed generated method: a
    /// type-qualified path found the generated inherent function first in
    /// v2.1; a trait-qualified path (`Trait::name`, `<T as Trait>::name`)
    /// names the trait's method in both versions. The paginate rule's
    /// `paginate`, which it rewrites only as a method call, is reported
    /// under that rule's code.
    fn removed_path(&mut self, node: &syn::ExprPath, arguments: Option<usize>) {
        let segments = &node.path.segments;
        let Some(method) = segments.last().map(|segment| &segment.ident) else {
            return;
        };
        let name = canonical(method);
        if !self.may_be_removed(&name) && name != "paginate" {
            return;
        }
        let Some(receiver) = self.qualified_path_receiver(node) else {
            return;
        };
        let arity = match arguments {
            Some(0) => return,
            Some(count) => Some(count - 1),
            None => None,
        };
        let form = match arguments {
            Some(_) => "this type-qualified call".to_owned(),
            None => format!("the function value `{}`", self.text(node)),
        };
        let removal = self.qualified_removal(&receiver, &name, arity);
        let offset = self.span(method.span()).start;
        let text = self.text(node);
        let prefix = text
            .rsplit_once("::")
            .map_or_else(String::new, |(prefix, _)| format!("{prefix}::"));
        if name == "paginate" {
            self.report_paginate_path(offset, removal, &form);
            return;
        }
        self.report_removed(offset, &name, removal.manual(), &form, (&prefix, ""));
    }

    /// The type a qualified path `Type::name` or `<Type>::name` names, or
    /// `None` when the path cannot name a generated inherent function: a
    /// trait-qualified path (`<T as Trait>::name`) or a single segment.
    fn qualified_path_receiver(&self, node: &syn::ExprPath) -> Option<Receiver> {
        let segments = &node.path.segments;
        match &node.qself {
            Some(qself) if qself.position == 0 && segments.len() == 1 => {
                Some(self.receiver_for_type(&qself.ty))
            }
            Some(_) => None,
            None if segments.len() < 2 => None,
            None => {
                let mut prefix = node.path.clone();
                prefix.segments.pop();
                let (resolved, cause) = self
                    .index
                    .model
                    .resolve_type_path_traced(self.context(), &prefix);
                Some(Receiver::from_traced(resolved, cause))
            }
        }
    }

    /// Whether the qualified path `Type::name` on `receiver` (`Type`) named
    /// a removed generated method (all dispositions).
    fn qualified_removal(&self, receiver: &Receiver, name: &str, arity: Option<usize>) -> Removal {
        // A qualified path names the type itself: a wrapper has no generated
        // associated functions.
        match receiver {
            Receiver::Wrapped(..) => Removal::None,
            receiver => {
                let dispatch = self.qualified_call(receiver, name);
                self.removal(&dispatch, receiver, name, arity)
            }
        }
    }

    /// A qualified path ending in the removed generated method `name` (at
    /// `trees[end]`) inside a macro the tool does not expand: a call
    /// `Type::name(..)`, a grouped callee `(Type::name)(..)` or a function
    /// value `Type::name`. The macro may use the tokens in any way, so the
    /// site is never a proved call: a path to a generated type (or one not
    /// resolved) is reported as possible, with the macro as the reason; a
    /// trait-qualified path, or one proved to name another type, is not.
    /// `paginate` is reported by the paginate rule only.
    fn removed_path_in_macro(
        &mut self,
        trees: &[TokenTree],
        end: usize,
        name: &str,
        offset: usize,
        context: &str,
    ) {
        if !self.may_be_removed(name) && name != "paginate" {
            return;
        }
        let why = format!(
            "it is inside {context}, which the tool does not expand (the macro may use the tokens in any way)"
        );
        let path = macro_path_start(trees, end)
            .map(|start| trees[start..=end].iter().cloned().collect::<TokenStream>())
            .and_then(|tokens| syn::parse2::<syn::ExprPath>(tokens).ok());
        let receiver = match &path {
            Some(path) => match self.qualified_path_receiver(path) {
                Some(receiver) => receiver,
                None => return,
            },
            None => Receiver::Unknown(Why::new(why.clone())),
        };
        let removal = match self.qualified_removal(&receiver, name, None) {
            Removal::Proved(hits) => Removal::Maybe(hits, why.clone()),
            Removal::Maybe(hits, _) => Removal::Maybe(hits, why.clone()),
            other => other,
        };
        let arguments_follow = matches!(
            trees.get(end + 1),
            Some(TokenTree::Group(group)) if group.delimiter() == proc_macro2::Delimiter::Parenthesis
        );
        let text = path
            .as_ref()
            .map_or_else(|| name.to_owned(), |path| self.text(path));
        let form = if arguments_follow {
            "this type-qualified call".to_owned()
        } else {
            format!("the path `{text}` (a possible function value)")
        };
        if name == "paginate" {
            self.report_paginate_path(offset, removal, &form);
            return;
        }
        let prefix = text
            .rsplit_once("::")
            .map_or_else(String::new, |(prefix, _)| format!("{prefix}::"));
        self.report_removed(offset, name, removal.manual(), &form, (&prefix, ""));
    }

    /// A type-qualified call or function value that may name the removed
    /// generated `paginate`: the paginate rule rewrites only method calls,
    /// so it is reported under that rule's code and left unchanged.
    fn report_paginate_path(&mut self, offset: usize, removal: Removal, form: &str) {
        let proof = match removal {
            Removal::Proved(hits)
                if hits
                    .iter()
                    .all(|(_, removed)| removed.disposition == PAGINATE_RULE) =>
            {
                format!(
                    "it names the generated `{}`",
                    self.generated_name(hits[0].0)
                )
            }
            Removal::Maybe(hits, why)
                if hits
                    .iter()
                    .any(|(_, removed)| removed.disposition == PAGINATE_RULE) =>
            {
                format!("it may name a generated paginated request, but {why}")
            }
            _ => return,
        };
        self.diagnostics.push(
            RawDiagnostic::new(
                Code::PaginateUnresolved,
                offset,
                format!(
                    "{form} may be the v2.1 generated traversal `paginate`, which v3 removes ({proof}); the tool rewrites only `.paginate(PageLimit::..)` method calls, so it was left unchanged. If it is Concord's, select the v3 terminal explicitly (`.collect_prefix(n)` -> `Prefix<Item>`, `.collect_all(n)`, or `.pages(n)`)"
                ),
            )
            .suggest(TERMINALS),
        );
    }

    /// A call of `name` inside a macro the tool does not expand: its
    /// receiver is unknown (see [`Self::removal`]).
    fn removed_in_macro(&mut self, name: &str, offset: usize, context: &str) {
        if !self.may_be_removed(name) {
            return;
        }
        let why = Why::new(format!(
            "it is inside {context}, which the tool does not expand (the macro may use the tokens in any way)"
        ));
        let removal = self
            .removal(
                &Dispatch::Unknown(why.clone()),
                &Receiver::Unknown(why),
                name,
                None,
            )
            .manual();
        self.report_removed(offset, name, removal, "this call", (".", "(..)"));
    }

    /// Whether `attributes` (of `node`) include an attribute macro whose
    /// expansion the tool does not know; if so, `node`'s tokens are scanned
    /// as that macro's input instead of being walked.
    fn annotated_by_unknown_macro(
        &mut self,
        attributes: &[syn::Attribute],
        node: &impl ToTokens,
    ) -> bool {
        let Some(attribute) = self
            .index
            .model
            .unknown_attribute_macro(self.scope, attributes)
        else {
            return false;
        };
        let context = format!("the item annotated with the attribute macro `{attribute}`");
        self.scan_macro_tokens(node.to_token_stream(), &context);
        true
    }

    /// Scans the tokens of a macro invocation the tool does not expand (any
    /// macro but a standard-library macro that evaluates its arguments in
    /// place, and the token-only standard macros): `context` says which.
    /// Nothing in it is rewritten. A generated setter, `.paginate(..)` or
    /// builder reference that may be there is reported instead of being
    /// silently left with a changed v3 meaning, and `PageLimit` and
    /// `PaginatedRequest` references keep their Concord imports.
    fn scan_macro_tokens(&mut self, tokens: TokenStream, context: &str) {
        let trees = tokens.into_iter().collect::<Vec<_>>();
        for (index, tree) in trees.iter().enumerate() {
            match tree {
                TokenTree::Group(group) => self.scan_macro_tokens(group.stream(), context),
                TokenTree::Ident(ident) => {
                    let name = canonical(ident);
                    let offset = self.span(ident.span()).start;
                    let preceded = |character: char| {
                        index > 0
                            && matches!(&trees[index - 1], TokenTree::Punct(punct) if punct.as_char() == character)
                    };
                    // Only a bare `PageLimit` can be resolved from these
                    // tokens; a qualified one always counts as a reference.
                    let qualified = preceded(':');
                    if name == "PageLimit"
                        && self.concord_file
                        && (qualified
                            || self.concord_identity_in(
                                self.scope,
                                false,
                                &["PageLimit".to_owned()],
                                "PageLimit",
                            ) != Identity::Other)
                    {
                        self.page_limit_references.push(offset);
                    }
                    if name == "PaginatedRequest"
                        && self.concord_file
                        && (qualified
                            || self.concord_identity_in(
                                self.scope,
                                false,
                                &["PaginatedRequest".to_owned()],
                                "PaginatedRequest",
                            ) != Identity::Other)
                        && !self.paginated_request_references.contains(&offset)
                    {
                        self.paginated_request_references.push(offset);
                    }
                    if let Some(client) = self.index.builder_client(&name) {
                        let reason = format!(
                            "it is inside {context}, which the tool does not expand (the macro may use the tokens in any way)"
                        );
                        self.builder_unresolved(client, offset, &reason);
                        continue;
                    }
                    let called = preceded('.') || qualified;
                    if name == "paginate" && preceded('.') && self.concord_file {
                        self.diagnostics.push(
                            RawDiagnostic::new(
                                Code::PaginateUnresolved,
                                offset,
                                format!(
                                    "`.paginate(..)` inside {context} may be the v2.1 generated traversal, but the tool does not expand that macro (it may rebind, reorder or stringify its arguments); the call was left unchanged. If it is Concord's, select the v3 terminal explicitly (`.collect_prefix(n)` -> `Prefix<Item>`, `.collect_all(n)`, or `.pages(n)`)"
                                ),
                            )
                            .suggest(TERMINALS),
                        );
                        continue;
                    }
                    if called {
                        self.shadow_in_macro(&name, offset, context);
                        if path_member(&trees, index) {
                            // `Type::name`, `<Type>::name`: a call, a
                            // grouped callee `(Type::name)(..)` or a
                            // function value; not a nested macro
                            // `log::debug!` or a module `a::name::b`.
                            self.removed_path_in_macro(&trees, index, &name, offset, context);
                        } else {
                            // `.name` is a method only when called: `(..)`
                            // follows (a bare `.name` is a field access).
                            let arguments_follow = matches!(
                                trees.get(index + 1),
                                Some(TokenTree::Group(group))
                                    if group.delimiter() == proc_macro2::Delimiter::Parenthesis
                            );
                            if arguments_follow {
                                self.removed_in_macro(&name, offset, context);
                            }
                        }
                    }
                    let Some(value) = name.strip_prefix("set_") else {
                        continue;
                    };
                    if !called || value.is_empty() {
                        continue;
                    }
                    let Some(owner) = self.index.optional_value_owner(value) else {
                        continue;
                    };
                    let replacement = renamed(ident, &format!("replace_{value}"));
                    self.diagnostics.push(
                        RawDiagnostic::new(
                            Code::SetterUnresolved,
                            offset,
                            format!(
                                "`set_{value}` inside {context} may target a Concord-optional value `{value}` declared {owner}, but the tool does not expand that macro (it may rebind, reorder or stringify its arguments); the call was left unchanged. If it is the optional value, v2.1 exact replacement is `replace_{value}`"
                            ),
                        )
                        .suggest(format!(".{replacement}(..)")),
                    );
                }
                _ => {}
            }
        }
    }

    fn migrate_setter(
        &mut self,
        method: &Ident,
        value: &str,
        dispatch: Dispatch,
        suggestion: String,
    ) {
        let method_range = self.span(method.span());
        match dispatch {
            Dispatch::Generated(owners) => {
                let found = owners
                    .iter()
                    .filter_map(|owner| self.value_optionality(*owner, value))
                    .collect::<Vec<_>>();
                if found.is_empty() || found.iter().all(|optional| !optional) {
                    return;
                }
                if found.iter().all(|optional| *optional) {
                    let result = self.edits.replace(
                        method_range.clone(),
                        renamed(method, &format!("replace_{value}")),
                    );
                    self.record(result, method_range.start);
                    self.diagnostics.push(RawDiagnostic::new(
                        Code::SetterReplace,
                        method_range.start,
                        format!(
                            "`set_{value}` targets the Concord-optional value `{value}`; v2.1 exact outer-slot replacement is v3 `replace_{value}` (v3 `set_{value}` would set a present payload, including an inner `None`)"
                        ),
                    ));
                } else {
                    self.diagnostics.push(
                        RawDiagnostic::new(
                            Code::SetterAmbiguous,
                            method_range.start,
                            format!(
                                "`set_{value}` may target both an optional and a required `{value}` depending on the receiver; migrate optional uses to `replace_{value}`"
                            ),
                        )
                        .suggest(suggestion),
                    );
                }
            }
            // A generated type without that generated setter (the call is the
            // application's own method), or a configuration builder method.
            Dispatch::Undefined | Dispatch::Config => {}
            Dispatch::Elsewhere(_) | Dispatch::Unknown(_) => {
                let Some(owner) = self.index.optional_value_owner(value) else {
                    return;
                };
                let reason = match &dispatch {
                    Dispatch::Elsewhere(reason) => reason.as_str(),
                    Dispatch::Unknown(why) => why.text().unwrap_or(UNPROVED_CALL),
                    _ => UNPROVED_CALL,
                };
                self.diagnostics.push(
                    RawDiagnostic::new(
                        Code::SetterUnresolved,
                        method_range.start,
                        format!(
                            "`set_{value}` may target a Concord-optional value `{value}` declared {owner}, but {reason}; the call was left unchanged. If it is the optional value, v2.1 exact replacement is `replace_{value}`"
                        ),
                    )
                    .suggest(suggestion),
                );
            }
        }
    }

    /// `.paginate(..)`: rewritten only when [`Self::proved_paginate`] holds.
    /// Otherwise the call is left unchanged; it is reported unless it is
    /// proved not to be Concord's (a constructor of a local `PageLimit` on a
    /// receiver that is not a generated request, or a runtime configuration
    /// builder).
    fn paginate(&mut self, node: &syn::ExprMethodCall) {
        let argument = &node.args[0];
        let method_range = self.span(node.method.span());
        let Some((variant, inner)) = self.proved_paginate(node) else {
            let constructor = page_limit_constructor(argument).map(|(variant, inner, path)| {
                let identity = self.concord_identity(path, path.segments.len() - 1, "PageLimit");
                (variant, inner, identity)
            });
            let terminal = constructor.map(|(variant, _, _)| terminal_method(variant));
            let (dispatch, _) = self.method_call_rewriting(node, terminal);
            let generated = Self::generated_paginate(&dispatch);
            match (&dispatch, constructor) {
                (Dispatch::Config, _) => {}
                // A generated request given something other than a Concord
                // `PageLimit` constructor: the terminal cannot be chosen.
                (_, None | Some((_, _, Identity::Other))) if generated => {
                    self.diagnostics.push(
                        RawDiagnostic::new(
                            Code::PaginateDynamic,
                            method_range.start,
                            "`paginate` receives a runtime `PageLimit`; v3 has distinct terminals with different output types, so the tool cannot choose one",
                        )
                        .suggest(TERMINALS),
                    );
                }
                // Another type's `paginate` taking its own `PageLimit`.
                (_, Some((_, _, Identity::Other))) => {}
                (_, constructor) => {
                    let reason = match &dispatch {
                        _ if generated => {
                            "its `PageLimit` could not be proved to be Concord's".to_owned()
                        }
                        Dispatch::Undefined => "its receiver is a generated type without a generated `paginate` (only the request of an endpoint with a `paginate` clause has one), so the call is the application's own method".to_owned(),
                        Dispatch::Elsewhere(reason) => reason.clone(),
                        Dispatch::Unknown(why) if why.text().is_some() => {
                            why.text().unwrap_or_default().to_owned()
                        }
                        _ => "it could not be proved to reach the generated request's `paginate`: its receiver was not resolved to a generated request type, or a trait implemented in this crate may take precedence".to_owned(),
                    };
                    let suggestion = match constructor {
                        Some((variant, inner, _)) => format!(
                            ".{}({})",
                            renamed(&node.method, terminal_method(variant)),
                            self.text(inner)
                        ),
                        None => TERMINALS.to_owned(),
                    };
                    self.diagnostics.push(
                        RawDiagnostic::new(
                            Code::PaginateUnresolved,
                            method_range.start,
                            format!(
                                "`.paginate(..)` may be the v2.1 generated traversal, but {reason}; the call was left unchanged. If it is Concord's, select the v3 terminal explicitly (`.collect_prefix(n)` -> `Prefix<Item>`, `.collect_all(n)`, or `.pages(n)`)"
                            ),
                        )
                        .suggest(suggestion),
                    );
                }
            }
            return;
        };
        let awaited = self
            .prefix_awaited
            .iter()
            .find(|(offset, _)| *offset == method_range.start)
            .map(|(_, tried)| *tried);
        let (method, code, message) = match (variant, awaited) {
            (PageLimitVariant::Prefix, Some(true)) => (
                "collect_prefix",
                Code::PaginatePrefixItems,
                "`.paginate(PageLimit::Prefix(n)).await?` became `.collect_prefix(n).await?.into_items()`: the same `Vec<Item>` prefix, and `Prefix::summary()` now also states whether it is complete",
            ),
            (PageLimitVariant::Prefix, Some(false)) => (
                "collect_prefix",
                Code::PaginatePrefixItems,
                "`.paginate(PageLimit::Prefix(n)).await` became `.collect_prefix(n).await.map(|prefix| prefix.into_items())`: the same `Result<Vec<Item>, ApiError>`, and `Prefix::summary()` now also states whether it is complete",
            ),
            (PageLimitVariant::Prefix, None) => (
                "collect_prefix",
                Code::PaginatePrefix,
                "`.paginate(PageLimit::Prefix(n))` became `.collect_prefix(n)`, which resolves to `Prefix<Item>` (use `.into_items()`/`.summary()`) instead of `Vec<Item>`",
            ),
            (PageLimitVariant::CompleteWithin, _) => (
                "collect_all",
                Code::PaginateCollectAll,
                "`.paginate(PageLimit::CompleteWithin(n))` became `.collect_all(n)`; a remaining continuation at the bound is still an error, never a partial Vec",
            ),
        };
        let argument_range = self.range(argument);
        let inner_text = self.edits.render(self.source, self.range(inner));
        let result = self
            .edits
            .replace(method_range.clone(), renamed(&node.method, method));
        self.record(result, method_range.start);
        let result = self
            .edits
            .replace_subsuming(argument_range.clone(), inner_text);
        self.record(result, argument_range.start);
        self.rewritten_arguments.push(argument_range);
        self.diagnostics
            .push(RawDiagnostic::new(code, method_range.start, message));
    }

    fn nonzero(&mut self, node: &syn::ExprMethodCall, method: &str) {
        let argument = &node.args[0];
        // A primitive `.get()` argument is already migrated (v2.1 required
        // the NonZero value itself), so a second run is a no-op.
        if matches!(argument, Expr::MethodCall(call) if call.method == "get" && call.args.is_empty())
        {
            return;
        }
        let argument_range = self.range(argument);
        let receiver = match (self.infer(&node.receiver), &self.mounted) {
            (Receiver::RuntimeConfig, Some(reason)) => Receiver::Unknown(Why::new(reason.clone())),
            (receiver, _) => receiver,
        };
        match receiver {
            Receiver::RuntimeConfig => {
                let result = if suffix_safe(argument) {
                    self.edits.insert(argument_range.end, ".get()")
                } else {
                    self.edits
                        .insert(argument_range.start, "(")
                        .and_then(|()| self.edits.insert(argument_range.end, ").get()"))
                };
                self.record(result, argument_range.start);
                self.diagnostics.push(RawDiagnostic::new(
                    Code::RuntimeNonZero,
                    argument_range.start,
                    format!(
                        "`{method}` takes a primitive in v3; the validated NonZero argument now passes `.get()` and aggregate validation stays at build"
                    ),
                ));
            }
            receiver @ (Receiver::Struct(_)
            | Receiver::Wrapped(..)
            | Receiver::External(_)
            | Receiver::Foreign
            | Receiver::Unknown(_)) => {
                let argument = self.text(argument);
                let cause = match &receiver {
                    Receiver::Unknown(why) => why
                        .text()
                        .map_or_else(String::new, |text| format!(" ({text})")),
                    _ => String::new(),
                };
                self.diagnostics.push(
                    RawDiagnostic::new(
                        Code::RuntimeNonZeroUnresolved,
                        argument_range.start,
                        format!(
                            "`{method}` may be the v2.1 runtime configuration setter whose NonZero argument becomes a primitive in v3, but its receiver is unresolved{cause}"
                        ),
                    )
                    .suggest(format!(".{method}({argument}.get())")),
                );
            }
            Receiver::Owners(_) | Receiver::HttpConfig => {}
        }
    }

    fn concord_trait(&self, path: &syn::Path) -> Option<String> {
        let last = path.segments.last()?.ident.to_string();
        if path.segments.len() > 1 {
            let first = path.segments.first()?.ident.to_string();
            return (is_concord_crate(&first)).then_some(last);
        }
        match self.imports.resolve(&last) {
            Some(full) => full
                .first()
                .is_some_and(|first| is_concord_crate(first))
                .then_some(last),
            None => self.imports.has_concord_glob().then_some(last),
        }
    }

    fn check_impl(&mut self, node: &syn::ItemImpl) {
        let Some((path, _)) = &node.trait_ else {
            return;
        };
        let Some(name) = self.concord_trait(path) else {
            return;
        };
        let self_type = self.text(&*node.self_ty);
        let at = self.range(path).start;
        let has_fn = |name: &str| {
            node.items
                .iter()
                .any(|item| matches!(item, ImplItem::Fn(function) if function.sig.ident == name))
        };
        let has_const = |name: &str| {
            node.items
                .iter()
                .any(|item| matches!(item, ImplItem::Const(constant) if constant.ident == name))
        };
        let has_type = |name: &str| {
            node.items
                .iter()
                .any(|item| matches!(item, ImplItem::Type(ty) if ty.ident == name))
        };
        match name.as_str() {
            "ResponseRepresentation" | "RecordDecoder" | "DecodeBody" => {
                for item in &node.items {
                    let ImplItem::Fn(function) = item else {
                        continue;
                    };
                    if function.sig.ident != "accept" || !function.sig.inputs.is_empty() {
                        continue;
                    }
                    let value = match function.block.stmts.as_slice() {
                        [syn::Stmt::Expr(expression, None)] => self.text(expression),
                        _ => "/* the static media range */".to_owned(),
                    };
                    self.diagnostics.push(
                        RawDiagnostic::new(
                            Code::AcceptConst,
                            self.span(function.sig.ident.span()).start,
                            format!(
                                "`{name}` for `{self_type}` negotiates with `fn accept()`; v3 reads a static `const ACCEPT` so inspection never runs user code"
                            ),
                        )
                        .suggest(format!("const ACCEPT: Option<&'static str> = {value};")),
                    );
                }
            }
            "RequestRepresentation" if has_fn("metadata") => {
                self.diagnostics.push(
                    RawDiagnostic::new(
                        Code::RequestRepresentation,
                        at,
                        format!(
                            "`RequestRepresentation` for `{self_type}` reports exact media facts in `metadata()`; v3 removes it and `prepare` returns a `PreparedBody` that owns Content-Type, length and replay facts"
                        ),
                    )
                    .suggest("const DESCRIPTION: BodyDescription = ..; fn prepare(input, context) -> Result<PreparedBody, BodyError> { Ok(PreparedBody::bytes(..).content_type(\"..\")?) }"),
                );
            }
            "RateKeyPart" if !has_const("ENCODING_ID") => {
                self.diagnostics.push(
                    RawDiagnostic::new(
                        Code::RateKeyPart,
                        at,
                        format!(
                            "`RateKeyPart` for `{self_type}` must name its canonical encoding contract; the tool cannot prove which name matches existing shared-limiter state"
                        ),
                    )
                    .suggest("const ENCODING_ID: &'static str = \"<stable-name>.v1\";"),
                );
            }
            "RateLimiter" => {
                self.diagnostics.push(RawDiagnostic::new(
                    Code::RateLimiterAtomic,
                    at,
                    format!(
                        "custom `RateLimiter` `{self_type}`: v3 requires all-or-none admission of the complete plan (no partial prefix debits), a capability descriptor (Local/Unenforced/SharedPersistent) and schema registration for shared state"
                    ),
                ));
            }
            "CredentialProvider" if !has_fn("http_origins") => {
                self.diagnostics.push(
                    RawDiagnostic::new(
                        Code::ProviderOrigins,
                        at,
                        format!(
                            "`CredentialProvider` for `{self_type}` declares no `http_origins`; v3 `ProviderHttp` rejects every destination outside that explicit allowlist"
                        ),
                    )
                    .suggest("fn http_origins(&self) -> &[ProviderOrigin] { &self.origins }"),
                );
            }
            "PaginationController" if !has_type("Init") => {
                self.diagnostics.push(
                    RawDiagnostic::new(
                        Code::PaginationControllerImpl,
                        at,
                        format!(
                            "`PaginationController` for `{self_type}` must separate public initialization data from private state"
                        ),
                    )
                    .suggest("type Init = ..; type Cursor = ..; fn start(init: Self::Init) -> Result<Self, PaginationError>; fn cursor(&self) -> Self::Cursor;"),
                );
            }
            "PageResponseRepresentation" => {
                self.diagnostics.push(RawDiagnostic::new(
                    Code::PageResponseRepresentation,
                    at,
                    format!(
                        "`PageResponseRepresentation` for `{self_type}` was removed; page eligibility is a Buffered driver plus a compatible controller"
                    ),
                ));
            }
            _ => {}
        }
    }

    /// Reports remaining `PageLimit` references and removes imports that are
    /// only used by rewritten `paginate` calls.
    fn finish_page_limit(&mut self, file: &syn::File) {
        if !self.concord_file {
            return;
        }
        let remaining = self
            .page_limit_references
            .iter()
            .copied()
            .filter(|offset| {
                !self
                    .rewritten_arguments
                    .iter()
                    .any(|range| range.contains(offset))
            })
            .collect::<Vec<_>>();
        for offset in &remaining {
            self.diagnostics.push(RawDiagnostic::new(
                Code::PageLimitReference,
                *offset,
                "`PageLimit` was removed in v3; select `.collect_prefix(n)`, `.collect_all(n)` or `.pages(n)` explicitly",
            ));
        }
        if !remaining.is_empty() {
            return;
        }
        let mut uses = Vec::new();
        self.collect_uses(&file.items, self.file_scope(), &mut uses);
        for (item, scope) in uses {
            self.remove_page_limit_import(item, scope);
        }
    }

    /// The module scope of this file in the crate model: every nested scope
    /// the visitor enters is restored on exit, so after the visit this is the
    /// file's own module.
    fn file_scope(&self) -> Option<ScopeId> {
        self.scope
    }

    /// `use` items of a file and of its inline modules, each with the scope
    /// its path is resolved in.
    fn collect_uses<'f>(
        &self,
        items: &'f [syn::Item],
        scope: Option<ScopeId>,
        output: &mut Vec<(&'f syn::ItemUse, Option<ScopeId>)>,
    ) {
        for item in items {
            match item {
                syn::Item::Use(item) => output.push((item, scope)),
                syn::Item::Mod(module) => {
                    if let Some((_, items)) = &module.content {
                        let offset = self.span(module.ident.span()).start;
                        let inner = self
                            .file
                            .and_then(|file| self.index.model.anchor(file, offset));
                        self.collect_uses(items, inner, output);
                    }
                }
                _ => {}
            }
        }
    }

    /// Whether the `use` path `prefix::name` (in `scope`) imports the
    /// Concord item `name`.
    fn imports_concord(
        &self,
        item: &syn::ItemUse,
        scope: Option<ScopeId>,
        prefix: &[String],
        name: &str,
    ) -> bool {
        let mut segments = prefix.to_vec();
        segments.push(name.to_owned());
        self.concord_identity_in(scope, item.leading_colon.is_some(), &segments, name)
            == Identity::Concord
    }

    fn remove_page_limit_import(&mut self, item: &syn::ItemUse, scope: Option<ScopeId>) {
        let mut prefix = Vec::new();
        let mut tree = &item.tree;
        loop {
            match tree {
                syn::UseTree::Path(path) => {
                    prefix.push(canonical(&path.ident));
                    tree = &path.tree;
                }
                syn::UseTree::Name(name) if name.ident == "PageLimit" => {
                    if self.imports_concord(item, scope, &prefix, "PageLimit") {
                        let range = removal_range(self.source, self.range(item));
                        let result = self.edits.replace_subsuming(range.clone(), "");
                        self.record(result, range.start);
                        self.import_removed(range.start);
                    }
                    return;
                }
                syn::UseTree::Group(group) => {
                    let items = group.items.iter().collect::<Vec<_>>();
                    let Some(position) = items.iter().position(|tree| {
                        matches!(tree, syn::UseTree::Name(name) if name.ident == "PageLimit")
                    }) else {
                        return;
                    };
                    if !self.imports_concord(item, scope, &prefix, "PageLimit") {
                        return;
                    }
                    let range = if items.len() == 1 {
                        removal_range(self.source, self.range(item))
                    } else if position + 1 < items.len() {
                        self.range(items[position]).start..self.range(items[position + 1]).start
                    } else {
                        self.range(items[position - 1]).end..self.range(items[position]).end
                    };
                    let result = self.edits.replace_subsuming(range.clone(), "");
                    self.record(result, range.start);
                    self.import_removed(range.start);
                    return;
                }
                _ => return,
            }
        }
    }

    /// Whether `path` names Concord's v2.1 `PaginatedRequest`, by
    /// declaration identity (`None` when its last segment is another name).
    fn paginated_request_identity(&self, path: &syn::Path) -> Option<Identity> {
        let last = path.segments.last()?;
        if last.ident != "PaginatedRequest" {
            return None;
        }
        Some(self.concord_identity(path, path.segments.len(), "PaginatedRequest"))
    }

    /// Whether `path` is a remaining reference to Concord's
    /// `PaginatedRequest`: proved, or unresolved but spelled through a
    /// Concord path or import (a local type with that name is not).
    fn is_paginated_request_reference(&self, path: &syn::Path) -> bool {
        match self.paginated_request_identity(path) {
            None | Some(Identity::Other) => false,
            Some(Identity::Concord) => true,
            Some(Identity::Unknown) => {
                if path.segments.len() > 1 {
                    return path
                        .segments
                        .first()
                        .is_some_and(|first| is_concord_crate(&first.ident.to_string()));
                }
                match self.imports.resolve("PaginatedRequest") {
                    Some(full) => full.first().is_some_and(|first| is_concord_crate(first)),
                    None => self.imports.has_concord_glob(),
                }
            }
        }
    }

    /// `let x: PaginatedRequest<_> = request.paginate(PageLimit::X(n));`
    /// selects exactly one v3 terminal type for the annotation, when the
    /// annotation is proved to be Concord's `PaginatedRequest` and the call
    /// is a proved (rewritten) traversal.
    fn paginated_request_annotation(&mut self, local: &syn::Local) {
        let (Pat::Type(typed), Some(init)) = (&local.pat, &local.init) else {
            return;
        };
        let Type::Path(ty) = typed.ty.as_ref() else {
            return;
        };
        if ty.qself.is_some()
            || self.paginated_request_identity(&ty.path) != Some(Identity::Concord)
        {
            return;
        }
        let last = ty.path.segments.last().expect("checked last segment");
        let inferred = match &last.arguments {
            syn::PathArguments::None => true,
            syn::PathArguments::AngleBracketed(arguments) => arguments
                .args
                .iter()
                .all(|argument| matches!(argument, syn::GenericArgument::Type(Type::Infer(_)))),
            syn::PathArguments::Parenthesized(_) => false,
        };
        let Expr::MethodCall(call) = peel(&init.expr) else {
            return;
        };
        if !inferred {
            return;
        }
        let Some((variant, _)) = self.proved_paginate(call) else {
            return;
        };
        let terminal = match variant {
            PageLimitVariant::Prefix => "CollectPrefix",
            PageLimitVariant::CompleteWithin => "CollectAll",
        };
        let range = self.span(last.ident.span());
        let result = self.edits.replace(range.clone(), terminal);
        self.record(result, range.start);
        self.rewritten_paginated_request.push(range.start);
        if ty.path.segments.len() == 1 && !self.imported_terminals.contains(&terminal) {
            self.imported_terminals.push(terminal);
        }
        self.diagnostics.push(RawDiagnostic::new(
            Code::PaginatedRequestType,
            range.start,
            format!(
                "`PaginatedRequest<_>` annotated a `.paginate(..)` value; the selected v3 terminal type is `{terminal}<_>`"
            ),
        ));
    }

    /// Reports remaining `PaginatedRequest` references, and otherwise turns
    /// its imports into imports of the terminal types the rewritten
    /// annotations use (or removes them).
    fn finish_paginated_request(&mut self, file: &syn::File) {
        if !self.concord_file {
            return;
        }
        let remaining = self
            .paginated_request_references
            .iter()
            .copied()
            .filter(|offset| !self.rewritten_paginated_request.contains(offset))
            .collect::<Vec<_>>();
        for offset in &remaining {
            self.diagnostics.push(
                RawDiagnostic::new(
                    Code::PaginatedRequestReference,
                    *offset,
                    "`PaginatedRequest<E>` was removed in v3: traversal terminals are `CollectPrefix<Item>`, `CollectAll<Item>` and `Pages<Item>`, typed by the item rather than the endpoint",
                )
                .suggest("CollectPrefix<Item> /* .collect_prefix(n) */ or CollectAll<Item> /* .collect_all(n) */ or Pages<Item> /* .pages(n) */"),
            );
        }
        if !remaining.is_empty() {
            return;
        }
        let mut terminals = self
            .imported_terminals
            .iter()
            .copied()
            .filter(|terminal| self.imports.resolve(terminal).is_none())
            .collect::<Vec<_>>();
        terminals.sort_unstable();
        let mut uses = Vec::new();
        self.collect_uses(&file.items, self.file_scope(), &mut uses);
        for (item, scope) in uses {
            self.rewrite_paginated_request_import(item, scope, &terminals);
        }
    }

    fn rewrite_paginated_request_import(
        &mut self,
        item: &syn::ItemUse,
        scope: Option<ScopeId>,
        terminals: &[&str],
    ) {
        let mut prefix = Vec::new();
        let mut tree = &item.tree;
        loop {
            match tree {
                syn::UseTree::Path(path) => {
                    prefix.push(canonical(&path.ident));
                    tree = &path.tree;
                }
                syn::UseTree::Name(name) if name.ident == "PaginatedRequest" => {
                    if !self.imports_concord(item, scope, &prefix, "PaginatedRequest") {
                        return;
                    }
                    let range = self.span(name.ident.span());
                    let result = match terminals {
                        [] => {
                            let range = removal_range(self.source, self.range(item));
                            self.edits.replace_subsuming(range, "")
                        }
                        [single] => self.edits.replace(range.clone(), *single),
                        _ => self
                            .edits
                            .replace(range.clone(), format!("{{{}}}", terminals.join(", "))),
                    };
                    self.record(result, range.start);
                    return;
                }
                syn::UseTree::Group(group) => {
                    let items = group.items.iter().collect::<Vec<_>>();
                    let Some(position) = items.iter().position(|tree| {
                        matches!(tree, syn::UseTree::Name(name) if name.ident == "PaginatedRequest")
                    }) else {
                        return;
                    };
                    if !self.imports_concord(item, scope, &prefix, "PaginatedRequest") {
                        return;
                    }
                    let result = if terminals.is_empty() {
                        let range = if items.len() == 1 {
                            removal_range(self.source, self.range(item))
                        } else if position + 1 < items.len() {
                            self.range(items[position]).start..self.range(items[position + 1]).start
                        } else {
                            self.range(items[position - 1]).end..self.range(items[position]).end
                        };
                        self.edits.replace_subsuming(range, "")
                    } else {
                        let range = self.range(items[position]);
                        self.edits.replace(range, terminals.join(", "))
                    };
                    let offset = self.range(items[position]).start;
                    self.record(result, offset);
                    return;
                }
                _ => return,
            }
        }
    }

    fn import_removed(&mut self, offset: usize) {
        self.diagnostics.push(RawDiagnostic::new(
            Code::PageLimitImport,
            offset,
            "removed the `PageLimit` import; every use was rewritten to an explicit v3 traversal terminal",
        ));
    }

    /// References to a v2.1 generated builder among the segments of a path.
    fn builder_path(&mut self, path: &syn::Path) {
        for (index, segment) in path.segments.iter().enumerate() {
            let name = canonical(&segment.ident);
            if self.index.builder_client(&name).is_none() {
                continue;
            }
            let segments = path
                .segments
                .iter()
                .take(index + 1)
                .map(|segment| canonical(&segment.ident))
                .collect::<Vec<_>>();
            let offset = self.span(segment.ident.span()).start;
            self.builder_reference(path.leading_colon.is_some(), &segments, offset);
        }
    }

    /// References to a v2.1 generated builder in a `use` tree.
    fn builder_use(&mut self, leading_colon: bool, tree: &syn::UseTree, prefix: &mut Vec<String>) {
        let ident = match tree {
            syn::UseTree::Path(path) => {
                prefix.push(canonical(&path.ident));
                self.builder_use(leading_colon, &path.tree, prefix);
                prefix.pop();
                return;
            }
            syn::UseTree::Group(group) => {
                for item in &group.items {
                    self.builder_use(leading_colon, item, prefix);
                }
                return;
            }
            syn::UseTree::Name(name) => &name.ident,
            syn::UseTree::Rename(rename) => &rename.ident,
            syn::UseTree::Glob(_) => return,
        };
        let name = canonical(ident);
        if self.index.builder_client(&name).is_none() {
            return;
        }
        let mut segments = prefix.clone();
        segments.push(name);
        let offset = self.span(ident.span()).start;
        self.builder_reference(leading_colon, &segments, offset);
    }

    /// v2.1 generates `ClientBuilder` beside the client, at the `api!`
    /// invocation; v3 generates it in the support module
    /// (`client::ClientBuilder`). A path whose segment `segments.last()` is
    /// proved to be the generated builder, found as an item there or through
    /// a glob, gets the support module inserted before that segment when the
    /// support module resolves at the same place; a path through an explicit
    /// import is left alone (the import itself is rewritten). A reference that
    /// cannot be rewritten is reported.
    fn builder_reference(&mut self, leading_colon: bool, segments: &[String], offset: usize) {
        let Some(name) = segments.last() else {
            return;
        };
        let first = &segments[0];
        if !leading_colon && segments.len() == 1 && self.generics.contains(first) {
            return;
        }
        let Some(named_client) = self.index.builder_client(name) else {
            return;
        };
        let index = self.index;
        let model = &index.model;
        let context = self.context();
        let client = match model.resolve_type_segments(context, leading_colon, segments) {
            TypeRes::Generated(owners)
                if !owners.is_empty()
                    && owners.iter().all(|owner| {
                        owner.role == Role::Builder && owner.client == owners[0].client
                    }) =>
            {
                owners[0].client
            }
            TypeRes::Unknown => {
                self.builder_unresolved(
                    named_client,
                    offset,
                    "the path could not be resolved to it (an item the tool cannot see may be in the way)",
                );
                return;
            }
            // Another type with the same name.
            _ => return,
        };
        if let Some(reason) = self.mounted.clone() {
            self.builder_unresolved(client, offset, &reason);
            return;
        }
        let support = to_snake_case(&self.index.clients[client].name);
        let provenance = match self.scope {
            Some(scope) => model.provenance(scope, leading_colon, segments),
            None => Provenance::Unknown,
        };
        match provenance {
            // The import naming it is rewritten where it is written.
            Provenance::Import => {}
            Provenance::Item | Provenance::Glob => {
                let mut support_path = segments[..segments.len() - 1].to_vec();
                support_path.push(support.clone());
                if model.support_module(context, leading_colon, &support_path) == Some(client) {
                    let result = self.edits.insert(offset, format!("{support}::"));
                    self.record(result, offset);
                    self.diagnostics.push(RawDiagnostic::new(
                        Code::BuilderPath,
                        offset,
                        format!(
                            "`{name}` is the builder generated by `api!` for client `{}`; v3 generates it in the support module, so this path now names `{support}::{name}`",
                            self.index.clients[client].name
                        ),
                    ));
                } else {
                    self.builder_unresolved(
                        client,
                        offset,
                        &format!(
                            "the generated support module `{support}` does not resolve at this place (another item takes its name)"
                        ),
                    );
                }
            }
            Provenance::Unknown => self.builder_unresolved(
                client,
                offset,
                "the tool could not tell how the path reaches it",
            ),
        }
    }

    fn builder_unresolved(&mut self, client: usize, offset: usize, reason: &str) {
        let client_name = &self.index.clients[client].name;
        let support = to_snake_case(client_name);
        self.diagnostics.push(
            RawDiagnostic::new(
                Code::BuilderPathUnresolved,
                offset,
                format!(
                    "`{client_name}Builder` may name the builder generated by `api!` for client `{client_name}`, which v3 moves from the level of the `api!` invocation into its support module (`{support}::{client_name}Builder`), but {reason}; the reference was left unchanged. If it is the generated builder, name it through the support module or use `{client_name}::builder()`"
                ),
            )
            .suggest(format!("{support}::{client_name}Builder")),
        );
    }
}

#[derive(Clone, Copy)]
enum PageLimitVariant {
    Prefix,
    CompleteWithin,
}

/// The v3 terminals, as a suggestion when none can be chosen.
const TERMINALS: &str = ".collect_prefix(pages) /* Prefix<Item> */ or .collect_all(NonZeroU32) /* Vec<Item> */ or .pages(pages)";

/// The v3 terminal a `PageLimit` variant migrates to.
const fn terminal_method(variant: PageLimitVariant) -> &'static str {
    match variant {
        PageLimitVariant::Prefix => "collect_prefix",
        PageLimitVariant::CompleteWithin => "collect_all",
    }
}

/// Whether `trees[index]` is `Punct(character)`.
fn punct_at(trees: &[TokenTree], index: usize, character: char) -> bool {
    matches!(trees.get(index), Some(TokenTree::Punct(punct)) if punct.as_char() == character)
}

/// Whether the identifier at `trees[index]` (in opaque macro tokens) is the
/// last segment of a qualified path, `a::name` or `<T>::name` (also with a
/// turbofish `name::<..>`): it is preceded by `::` and not followed by `!`
/// (a nested macro, `log::debug!`) or by `::` and another segment (a module
/// or type segment, `a::name::b`).
fn path_member(trees: &[TokenTree], index: usize) -> bool {
    let preceded = index >= 2 && punct_at(trees, index - 1, ':') && punct_at(trees, index - 2, ':');
    let macro_name = punct_at(trees, index + 1, '!');
    let inner_segment = punct_at(trees, index + 1, ':')
        && punct_at(trees, index + 2, ':')
        && !punct_at(trees, index + 3, '<');
    preceded && !macro_name && !inner_segment
}

/// Whether `ident` may start or continue a path segment: an identifier, a
/// raw identifier or a path keyword (`self`, `Self`, `super`, `crate`); not
/// another keyword such as `return` before a path.
fn segment_ident(ident: &Ident) -> bool {
    matches!(
        ident.to_string().as_str(),
        "self" | "Self" | "super" | "crate"
    ) || syn::parse_str::<Ident>(&ident.to_string()).is_ok()
}

/// The index of the `<` matching the `>` at `trees[close]` (a `->` inside
/// the brackets does not count).
fn matching_open(trees: &[TokenTree], close: usize) -> Option<usize> {
    let mut depth = 0usize;
    for index in (0..=close).rev() {
        let TokenTree::Punct(punct) = &trees[index] else {
            continue;
        };
        match punct.as_char() {
            '>' if !(index > 0 && punct_at(trees, index - 1, '-')) => depth += 1,
            '<' => {
                depth = depth.checked_sub(1)?;
                if depth == 0 {
                    return Some(index);
                }
            }
            _ => {}
        }
    }
    None
}

/// The index of the first token of the qualified path whose last segment is
/// `trees[end]` in opaque macro tokens (`a::b::name`, `::a::name`,
/// `<T>::name`, `<T as Trait>::name`, `A::<X>::name`), or `None` when the
/// brackets before it do not balance.
fn macro_path_start(trees: &[TokenTree], end: usize) -> Option<usize> {
    let mut start = end;
    loop {
        if start < 2 || !punct_at(trees, start - 1, ':') || !punct_at(trees, start - 2, ':') {
            return Some(start);
        }
        let colons = start - 2;
        let Some(before) = colons.checked_sub(1) else {
            return Some(colons);
        };
        match &trees[before] {
            TokenTree::Ident(ident) if segment_ident(ident) => start = before,
            TokenTree::Punct(punct) if punct.as_char() == '>' => {
                let open = matching_open(trees, before)?;
                let ident_at = |index: usize| matches!(&trees[index], TokenTree::Ident(ident) if segment_ident(ident));
                if open >= 1 && ident_at(open - 1) {
                    // `Type<A>::name`
                    start = open - 1;
                } else if open >= 3
                    && punct_at(trees, open - 1, ':')
                    && punct_at(trees, open - 2, ':')
                    && ident_at(open - 3)
                {
                    // `Type::<A>::name`
                    start = open - 3;
                } else {
                    // `<T>::name`, `<T as Trait>::name`
                    return Some(open);
                }
            }
            // A leading `::`.
            _ => return Some(colons),
        }
    }
}

/// `new` spelled like `original`: a raw identifier (`r#set_x`) stays raw
/// (`r#replace_x`).
fn renamed(original: &Ident, new: &str) -> String {
    if original.to_string().starts_with("r#") {
        format!("r#{new}")
    } else {
        new.to_owned()
    }
}

/// Whether an external path is in the standard library or Concord.
fn is_std_or_concord(path: &[String]) -> bool {
    path.first().is_some_and(|first| {
        is_concord_crate(first) || matches!(first.as_str(), "std" | "core" | "alloc")
    })
}

/// Collects every name a pattern binds; `false` when a macro in it may bind
/// names the tool cannot see.
fn pattern_names(pattern: &Pat, names: &mut Vec<String>) -> bool {
    match pattern {
        Pat::Ident(ident) => {
            names.push(ident.ident.to_string());
            ident
                .subpat
                .as_ref()
                .is_none_or(|(_, subpattern)| pattern_names(subpattern, names))
        }
        Pat::Macro(_) | Pat::Verbatim(_) => false,
        Pat::Type(typed) => pattern_names(&typed.pat, names),
        Pat::Reference(reference) => pattern_names(&reference.pat, names),
        Pat::Paren(paren) => pattern_names(&paren.pat, names),
        Pat::Tuple(tuple) => tuple
            .elems
            .iter()
            .all(|element| pattern_names(element, names)),
        Pat::TupleStruct(tuple) => tuple
            .elems
            .iter()
            .all(|element| pattern_names(element, names)),
        Pat::Struct(structure) => structure
            .fields
            .iter()
            .all(|field| pattern_names(&field.pat, names)),
        Pat::Slice(slice) => slice
            .elems
            .iter()
            .all(|element| pattern_names(element, names)),
        Pat::Or(alternatives) => alternatives
            .cases
            .iter()
            .all(|case| pattern_names(case, names)),
        _ => true,
    }
}

/// The spelling `PageLimit::Prefix(n)` / `PageLimit::CompleteWithin(n)`, with
/// its path (whose prefix up to `PageLimit` still has to be proved to name
/// Concord's type, see `CallerVisitor::concord_page_limit`).
fn page_limit_constructor(argument: &Expr) -> Option<(PageLimitVariant, &Expr, &syn::Path)> {
    let Expr::Call(call) = argument else {
        return None;
    };
    let Expr::Path(path) = call.func.as_ref() else {
        return None;
    };
    if path.qself.is_some() {
        return None;
    }
    let segments = path
        .path
        .segments
        .iter()
        .map(|segment| segment.ident.to_string())
        .collect::<Vec<_>>();
    let [.., owner, variant] = segments.as_slice() else {
        return None;
    };
    if owner != "PageLimit" || call.args.len() != 1 {
        return None;
    }
    let variant = match variant.as_str() {
        "Prefix" => PageLimitVariant::Prefix,
        "CompleteWithin" => PageLimitVariant::CompleteWithin,
        _ => return None,
    };
    Some((variant, &call.args[0], &path.path))
}

/// Whether `.get()` can be appended without changing precedence.
fn suffix_safe(expression: &Expr) -> bool {
    matches!(
        expression,
        Expr::Path(_)
            | Expr::MethodCall(_)
            | Expr::Call(_)
            | Expr::Field(_)
            | Expr::Index(_)
            | Expr::Paren(_)
            | Expr::Macro(_)
            | Expr::Try(_)
            | Expr::Await(_)
            | Expr::Lit(_)
    )
}

impl<'ast> Visit<'ast> for CallerVisitor<'_, '_> {
    /// An item annotated with an attribute macro whose expansion is not
    /// known is that macro's input: nothing in it is rewritten.
    fn visit_item(&mut self, node: &'ast syn::Item) {
        if !self.annotated_by_unknown_macro(item_attributes(node).unwrap_or_default(), node) {
            syn::visit::visit_item(self, node);
        }
    }

    fn visit_impl_item(&mut self, node: &'ast syn::ImplItem) {
        let attributes = match node {
            ImplItem::Const(member) => &member.attrs[..],
            ImplItem::Fn(member) => &member.attrs,
            ImplItem::Type(member) => &member.attrs,
            ImplItem::Macro(member) => &member.attrs,
            _ => &[],
        };
        if !self.annotated_by_unknown_macro(attributes, node) {
            syn::visit::visit_impl_item(self, node);
        }
    }

    fn visit_trait_item(&mut self, node: &'ast syn::TraitItem) {
        let attributes = match node {
            syn::TraitItem::Const(member) => &member.attrs[..],
            syn::TraitItem::Fn(member) => &member.attrs,
            syn::TraitItem::Type(member) => &member.attrs,
            syn::TraitItem::Macro(member) => &member.attrs,
            _ => &[],
        };
        if !self.annotated_by_unknown_macro(attributes, node) {
            syn::visit::visit_trait_item(self, node);
        }
    }

    fn visit_item_mod(&mut self, node: &'ast syn::ItemMod) {
        if node.content.is_none() {
            return;
        }
        let saved = self.enter(self.span(node.ident.span()).start);
        let bindings = std::mem::replace(&mut self.scopes, vec![Bindings::default()]);
        syn::visit::visit_item_mod(self, node);
        self.scopes = bindings;
        self.scope = saved;
    }

    fn visit_item_fn(&mut self, node: &'ast syn::ItemFn) {
        let generics = self.push_generics(&node.sig.generics);
        let saved = self.enter_function(&node.sig);
        syn::visit::visit_item_fn(self, node);
        self.scopes = saved;
        self.generics.truncate(generics);
    }

    fn visit_impl_item_fn(&mut self, node: &'ast syn::ImplItemFn) {
        let generics = self.push_generics(&node.sig.generics);
        let saved = self.enter_function(&node.sig);
        syn::visit::visit_impl_item_fn(self, node);
        self.scopes = saved;
        self.generics.truncate(generics);
    }

    fn visit_trait_item_fn(&mut self, node: &'ast syn::TraitItemFn) {
        let generics = self.push_generics(&node.sig.generics);
        let saved = self.enter_function(&node.sig);
        syn::visit::visit_trait_item_fn(self, node);
        self.scopes = saved;
        self.generics.truncate(generics);
    }

    fn visit_item_impl(&mut self, node: &'ast syn::ItemImpl) {
        if self.concord_file {
            self.check_impl(node);
        }
        let generics = self.push_generics(&node.generics);
        let self_type = self.index.model.resolve_type(self.context(), &node.self_ty);
        self.self_types.push(self_type);
        syn::visit::visit_item_impl(self, node);
        self.self_types.pop();
        self.generics.truncate(generics);
    }

    fn visit_item_trait(&mut self, node: &'ast syn::ItemTrait) {
        let generics = self.push_generics(&node.generics);
        self.self_types.push(TypeRes::Unknown);
        syn::visit::visit_item_trait(self, node);
        self.self_types.pop();
        self.generics.truncate(generics);
    }

    fn visit_item_use(&mut self, node: &'ast syn::ItemUse) {
        let mut prefix = Vec::new();
        self.builder_use(node.leading_colon.is_some(), &node.tree, &mut prefix);
    }

    fn visit_block(&mut self, node: &'ast syn::Block) {
        let saved = self.enter(self.span(node.brace_token.span.open()).start);
        let depth = self.scopes.len();
        self.scopes.push(Bindings {
            block: self.scope,
            ..Bindings::default()
        });
        for statement in &node.stmts {
            self.visit_stmt(statement);
            // A statement macro that may expand to `let` bindings or items
            // hides every earlier binding of this block and outer scopes.
            if let syn::Stmt::Macro(statement) = statement {
                if !self.imports.is_api_macro(&statement.mac.path)
                    && !self
                        .index
                        .model
                        .binding_free_macro(self.scope, &statement.mac.path)
                {
                    self.scopes.push(Bindings {
                        opaque: true,
                        ..Bindings::default()
                    });
                }
            }
        }
        self.scopes.truncate(depth);
        self.scope = saved;
    }

    /// Match-arm patterns bind names that shadow outer bindings.
    fn visit_arm(&mut self, node: &'ast syn::Arm) {
        self.scopes.push(Bindings::default());
        self.bind_pattern(&node.pat, Receiver::unknown());
        syn::visit::visit_arm(self, node);
        self.scopes.pop();
    }

    /// `if let` bindings are visible in the `then` branch only.
    fn visit_expr_if(&mut self, node: &'ast syn::ExprIf) {
        self.scopes.push(Bindings::default());
        self.visit_expr(&node.cond);
        self.visit_block(&node.then_branch);
        self.scopes.pop();
        if let Some((_, otherwise)) = &node.else_branch {
            self.visit_expr(otherwise);
        }
    }

    fn visit_expr_while(&mut self, node: &'ast syn::ExprWhile) {
        self.scopes.push(Bindings::default());
        self.visit_expr(&node.cond);
        self.visit_block(&node.body);
        self.scopes.pop();
    }

    fn visit_expr_let(&mut self, node: &'ast syn::ExprLet) {
        syn::visit::visit_expr_let(self, node);
        self.bind_pattern(&node.pat, Receiver::unknown());
    }

    fn visit_local(&mut self, node: &'ast syn::Local) {
        if let Some(init) = &node.init {
            self.visit_expr(&init.expr);
            if let Some((_, diverge)) = &init.diverge {
                self.visit_expr(diverge);
            }
        }
        if self.concord_file {
            self.paginated_request_annotation(node);
            if let Pat::Type(typed) = &node.pat {
                self.visit_type(&typed.ty);
            }
        }
        // A `let` gated by `#[cfg]`/`#[cfg_attr]` may not be compiled: the
        // names it binds (and shadows) are unknown after it.
        if attribute_effects(&node.attrs).gated {
            let location = self.location(node.let_token.span);
            self.bind_gated(&node.pat, &location);
            return;
        }
        let receiver = node
            .init
            .as_ref()
            .map_or(Receiver::unknown(), |init| self.infer(&init.expr));
        self.bind_pattern(&node.pat, receiver);
    }

    fn visit_expr_closure(&mut self, node: &'ast syn::ExprClosure) {
        self.scopes.push(Bindings::default());
        for input in &node.inputs {
            self.bind_pattern(input, Receiver::unknown());
        }
        self.visit_expr(&node.body);
        self.scopes.pop();
    }

    fn visit_expr_for_loop(&mut self, node: &'ast syn::ExprForLoop) {
        self.visit_expr(&node.expr);
        self.scopes.push(Bindings::default());
        self.bind_pattern(&node.pat, Receiver::unknown());
        self.visit_block(&node.body);
        self.scopes.pop();
    }

    fn visit_expr_method_call(&mut self, node: &'ast syn::ExprMethodCall) {
        let method = canonical(&node.method);
        let configured = match method.as_str() {
            "configure_runtime" => Some(Receiver::RuntimeConfig),
            "configure_http" => Some(Receiver::HttpConfig),
            _ => None,
        };
        match (configured, node.args.first()) {
            (Some(kind), Some(Expr::Closure(closure))) if node.args.len() == 1 => {
                self.visit_expr(&node.receiver);
                // The closure argument is Concord's configuration builder only
                // when the receiver is proved to be a generated client builder.
                let receiver = self.infer(&node.receiver);
                let builder = matches!(
                    &receiver,
                    Receiver::Owners(owners)
                        if owners.iter().all(|owner| owner.role == Role::Builder)
                );
                let kind = if builder {
                    kind
                } else {
                    let why = receiver.why();
                    Receiver::Unknown(Why::new(format!(
                        "the closure parameter of `{method}` is Concord's configuration builder only when the call's receiver is the generated client builder, which is not proved{}",
                        why.text()
                            .map_or_else(String::new, |text| format!(": {text}"))
                    )))
                };
                self.scopes.push(Bindings::default());
                for input in &closure.inputs {
                    self.bind_pattern(input, kind.clone());
                }
                self.visit_expr(&closure.body);
                self.scopes.pop();
            }
            _ => syn::visit::visit_expr_method_call(self, node),
        }
        self.check_method(node);
    }

    /// A path in call position is a call (see [`Self::ufcs_setter`]), not a
    /// function value.
    fn visit_expr_call(&mut self, node: &'ast syn::ExprCall) {
        for attribute in &node.attrs {
            self.visit_attribute(attribute);
        }
        match node.func.as_ref() {
            Expr::Path(path) => syn::visit::visit_expr_path(self, path),
            other => self.visit_expr(other),
        }
        for argument in &node.args {
            self.visit_expr(argument);
        }
        self.ufcs_setter(node);
        if let Expr::Path(path) = node.func.as_ref() {
            self.shadow_path(path, Some(node.args.len()));
            self.removed_path(path, Some(node.args.len()));
        }
    }

    /// A path in value position: a generated setter named as a function
    /// value is reported (see [`Self::setter_value`]).
    fn visit_expr_path(&mut self, node: &'ast syn::ExprPath) {
        self.setter_value(node);
        self.shadow_path(node, None);
        self.removed_path(node, None);
        syn::visit::visit_expr_path(self, node);
    }

    /// `x.paginate(PageLimit::Prefix(n)).await?` keeps its `Vec<Item>` type as
    /// `x.collect_prefix(n).await?.into_items()`.
    fn visit_expr_try(&mut self, node: &'ast syn::ExprTry) {
        let prefix = self
            .concord_file
            .then(|| self.awaited_prefix(&node.expr))
            .flatten()
            .map(|call| self.span(call.method.span()).start);
        if let Some(offset) = prefix {
            self.prefix_awaited.push((offset, true));
        }
        syn::visit::visit_expr_try(self, node);
        if prefix.is_some() {
            let end = self.range(node).end;
            let result = self.edits.insert(end, ".into_items()");
            self.record(result, end);
        }
    }

    /// `x.paginate(PageLimit::Prefix(n)).await` keeps its
    /// `Result<Vec<Item>, ApiError>` type through `.map(..into_items())`.
    fn visit_expr_await(&mut self, node: &'ast syn::ExprAwait) {
        let prefix = self
            .concord_file
            .then(|| self.prefix_call(&node.base))
            .flatten()
            .map(|call| self.span(call.method.span()).start)
            .filter(|offset| !self.prefix_awaited.iter().any(|(known, _)| known == offset));
        if let Some(offset) = prefix {
            self.prefix_awaited.push((offset, false));
        }
        syn::visit::visit_expr_await(self, node);
        if prefix.is_some() {
            let end = self.range(node).end;
            let result = self.edits.insert(end, ".map(|prefix| prefix.into_items())");
            self.record(result, end);
        }
    }

    /// Macro invocations are never expanded. The tool rewrites inside one
    /// only when its path resolves to a standard-library macro whose
    /// arguments are Rust expressions evaluated in place (`assert!`,
    /// `format!`, `vec!`, `write!`, ...; see [`ARGUMENT_MACROS`]), and then
    /// only in those expressions. A token-only standard macro (`stringify!`,
    /// `concat!`, ...) is left alone; any other macro (a crate-local
    /// `macro_rules!`, another crate's macro, `matches!`, a shadowed standard
    /// name) may rebind, reorder or stringify its arguments, so what may be a
    /// generated call inside it is reported, never rewritten.
    fn visit_macro(&mut self, node: &'ast syn::Macro) {
        if self.imports.is_api_macro(&node.path) {
            return;
        }
        if node.path.is_ident("macro_rules") {
            self.scan_macro_tokens(node.tokens.clone(), "a `macro_rules!` definition");
            return;
        }
        let context = format!("the arguments of `{}!`", path_text(&node.path));
        match self.index.model.std_macro(self.scope, &node.path) {
            Some(name) if ARGUMENT_MACROS.contains(&name.as_str()) => {
                match node.parse_body_with(Punctuated::<Expr, Token![,]>::parse_terminated) {
                    Ok(expressions) => {
                        for expression in &expressions {
                            self.visit_expr(expression);
                        }
                    }
                    Err(_) => self.scan_macro_tokens(node.tokens.clone(), &context),
                }
            }
            Some(name) if TOKEN_MACROS.contains(&name.as_str()) => {}
            _ => self.scan_macro_tokens(node.tokens.clone(), &context),
        }
    }

    fn visit_path(&mut self, node: &'ast syn::Path) {
        // A `PageLimit` segment is a remaining reference unless its path is
        // proved to name another type (a local `PageLimit` is not Concord's).
        if let Some(position) = node
            .segments
            .iter()
            .position(|segment| segment.ident == "PageLimit")
        {
            if self.concord_identity(node, position + 1, "PageLimit") != Identity::Other {
                let offset = self.span(node.segments[position].ident.span()).start;
                self.page_limit_references.push(offset);
            }
        }
        if self.concord_file && self.is_paginated_request_reference(node) {
            if let Some(segment) = node.segments.last() {
                let offset = self.span(segment.ident.span()).start;
                if !self.paginated_request_references.contains(&offset) {
                    self.paginated_request_references.push(offset);
                }
            }
        }
        self.builder_path(node);
        syn::visit::visit_path(self, node);
    }
}
